// « Le contre-exemple » : quatre-vingt-quinze énoncés faux et, pour chacun, quatre objets dont un seul le réfute (MEMO_atlas_activites.md §151 et §152).
import { T, contre } from './raisonner-outils.js';
const F = 'fondements', A = 'algebre', L = 'lineaire', N = 'analyse', Pr = 'probabilites', B = true;
const HF = ` L'hypothèse n'étant pas vérifiée, cet objet ne dit rien de l'énoncé.`, CV = ` Cet objet vérifie l'hypothèse et la conclusion : il illustre l'énoncé, il ne le réfute pas.`;
export default [
// ---------- Seconde ----------
contre('sec-carre-plus-grand', 'seconde', '', 's-07', 'x² ≥ x', T`« Pour tout réel $x$, on a $x^2 \geqslant x$. »`, [
  [T`$x = 2$`, T`$2^2 = 4 \geqslant 2$ : l'inégalité est vraie pour ce nombre, qui ne réfute donc rien.`],
  [T`$x = -1$`, T`$(-1)^2 = 1 \geqslant -1$ : l'inégalité est vraie pour ce nombre, qui ne réfute donc rien.`],
  [T`$x = \dfrac12$`, T`$\left(\dfrac12\right)^2 = \dfrac14$, qui est strictement inférieur à $\dfrac12$ : l'inégalité est fausse pour ce nombre.`, B],
  [T`$x = 1$`, T`$1^2 = 1 \geqslant 1$ : l'inégalité, qui est large, est vraie pour ce nombre.`] ],
  T`Entre 0 et 1, élever au carré diminue : $x^2 - x = x(x - 1)$ est strictement négatif exactement quand $0 < x < 1$. Pour réfuter un énoncé « pour tout », un seul nombre suffit, mais il faut le chercher là où l'intuition, formée sur les entiers, ne va pas.`),
contre('sec-racine-carre', 'seconde', '', 's-01', '√(x²) = x', T`« Pour tout réel $x$, on a $\sqrt{x^2} = x$. »`, [
  [T`$x = 3$`, T`$\sqrt{3^2} = \sqrt9 = 3$ : l'égalité est vraie pour ce nombre.`],
  [T`$x = 0$`, T`$\sqrt{0^2} = 0$ : l'égalité est vraie pour ce nombre.`],
  [T`$x = -4$`, T`$\sqrt{(-4)^2} = \sqrt{16} = 4$, qui n'est pas égal à $-4$ : l'égalité est fausse pour ce nombre.`, B],
  [T`$x = \dfrac12$`, T`$\sqrt{\dfrac14} = \dfrac12$ : l'égalité est vraie pour ce nombre.`] ],
  T`Une racine carrée est toujours positive : $\sqrt{x^2}$ vaut $x$ si $x$ est positif et $-x$ si $x$ est négatif. L'égalité n'est donc en défaut que pour les nombres strictement négatifs.`),
contre('sec-produit-inegalite', 'seconde', '', 's-09', 'Multiplier une inégalité', T`« Soit $a$, $b$ et $c$ trois réels. Si $a < b$, alors $ac < bc$. »`, [
  [T`$a = 1$, $b = 2$, $c = 3$`, T`$1 < 2$ et $3 < 6$.` + CV],
  [T`$a = -2$, $b = 5$, $c = 1$`, T`$-2 < 5$ et $-2 < 5$ encore après multiplication par 1.` + CV],
  [T`$a = 1$, $b = 2$, $c = -1$`, T`$1 < 2$, mais $ac = -1$ et $bc = -2$ : on a $-1 > -2$. L'hypothèse est vraie, la conclusion fausse.`, B],
  [T`$a = 2$, $b = 1$, $c = -1$`, T`$2 < 1$ est faux.` + HF] ],
  T`Multiplier les deux membres d'une inégalité par un nombre strictement négatif en change le sens ; par zéro, on obtient une égalité. Le sens n'est conservé que pour un multiplicateur strictement positif.`),
contre('sec-inverse-ordre', 'seconde', '', 's-07', 'L\'inverse renverse l\'ordre', T`« Soit $a$ et $b$ deux réels non nuls. Si $a < b$, alors $\dfrac1a > \dfrac1b$. »`, [
  [T`$a = 2$, $b = 4$`, T`$2 < 4$ et $\dfrac12 > \dfrac14$.` + CV],
  [T`$a = -4$, $b = -2$`, T`$-4 < -2$ et $-\dfrac14 > -\dfrac12$.` + CV],
  [T`$a = -2$, $b = 3$`, T`$-2 < 3$, mais $-\dfrac12 < \dfrac13$ : l'hypothèse est vraie, la conclusion fausse.`, B],
  [T`$a = 5$, $b = 1$`, T`$5 < 1$ est faux.` + HF] ],
  T`La fonction inverse est décroissante sur $]-\infty\,;\,0[$ et sur $]0\,;\,+\infty[$ : elle renverse l'ordre de deux nombres de même signe. Pour deux nombres de signes contraires, chaque inverse garde son signe et l'ordre est conservé.`),
contre('sec-divisible', 'seconde', '', '', 'Divisible par 2 et par 6', T`« Si un entier est divisible par 2 et par 6, alors il est divisible par 12. »`, [
  [T`L'entier 12`, T`12 est divisible par 2, par 6 et par 12.` + CV],
  [T`L'entier 24`, T`24 est divisible par 2, par 6 et par 12.` + CV],
  [T`L'entier 6`, T`6 est divisible par 2 et par 6, mais pas par 12 : l'hypothèse est vraie, la conclusion fausse.`, B],
  [T`L'entier 4`, T`4 n'est pas divisible par 6.` + HF] ],
  T`Être divisible par 2 et par 6 n'apprend rien de plus qu'être divisible par 6, puisque tout multiple de 6 est déjà pair. On ne peut multiplier les deux diviseurs que s'ils n'ont aucun diviseur commun autre que 1 : un entier divisible par 3 et par 4 est divisible par 12.`),
contre('sec-premier-impair', 'seconde', '', '', 'Premier donc impair', T`« Tout nombre premier est impair. »`, [
  [T`Le nombre 3`, T`3 est premier et impair.` + CV],
  [T`Le nombre 7`, T`7 est premier et impair.` + CV],
  [T`Le nombre 2`, T`2 est premier, car ses seuls diviseurs positifs sont 1 et 2, et il est pair : l'hypothèse est vraie, la conclusion fausse.`, B],
  [T`Le nombre 9`, T`$9 = 3 \times 3$ n'est pas premier.` + HF] ],
  T`2 est le seul nombre premier pair : tout autre nombre pair strictement positif est divisible par 2 sans être égal à 2, donc n'est pas premier. L'énoncé devient vrai si l'on écrit « tout nombre premier différent de 2 ».`),
contre('sec-taux-opposes', 'seconde', '', 's-06', 'Retour au prix de départ', T`« Si un prix retrouve sa valeur de départ après deux évolutions successives, alors les taux de ces deux évolutions sont opposés. »`, [
  [T`Une hausse de $25\,\%$, puis une baisse de $20\,\%$`, T`$1{,}25 \times 0{,}8 = 1$ : le prix retrouve sa valeur, et pourtant les taux $+25\,\%$ et $-20\,\%$ ne sont pas opposés. L'hypothèse est vraie, la conclusion fausse.`, B],
  [T`Une hausse de $10\,\%$, puis une baisse de $10\,\%$`, T`$1{,}1 \times 0{,}9 = 0{,}99$ : le prix ne retrouve pas sa valeur.` + HF],
  [T`Deux évolutions de taux $0\,\%$`, T`Le prix ne change pas, et les deux taux, nuls, sont opposés.` + CV],
  [T`Une hausse de $50\,\%$, puis une baisse de $50\,\%$`, T`$1{,}5 \times 0{,}5 = 0{,}75$ : le prix ne retrouve pas sa valeur.` + HF] ],
  T`Deux évolutions se compensent quand le produit de leurs coefficients multiplicateurs vaut 1, et non quand la somme de leurs taux est nulle. Hormis le cas où rien ne change, les taux de deux évolutions réciproques ne sont jamais opposés.`),
contre('sec-moyenne-valeur', 'seconde', '', 's-11', 'La moyenne est une valeur de la série', T`« La moyenne d'une série de nombres est toujours l'une des valeurs de la série. »`, [
  [T`La série 2 ; 4 ; 6`, T`Sa moyenne est 4, qui est une valeur de la série : cette série vérifie l'énoncé.`],
  [T`La série 5 ; 5 ; 5`, T`Sa moyenne est 5, qui est une valeur de la série : cette série vérifie l'énoncé.`],
  [T`La série 1 ; 2 ; 6`, T`Sa moyenne est $\dfrac{1 + 2 + 6}{3} = 3$, qui n'est aucune des trois valeurs : l'énoncé est faux pour cette série.`, B],
  [T`La série 0 ; 5 ; 10`, T`Sa moyenne est 5, qui est une valeur de la série : cette série vérifie l'énoncé.`] ],
  T`La moyenne est un point d'équilibre, pas une valeur observée : une famille peut avoir « en moyenne » 1,8 enfant. Elle est seulement comprise entre la plus petite et la plus grande valeur.`),
contre('sec-proba-somme', 'seconde', '', 's-03', 'P(A ∪ B) = P(A) + P(B)', T`On lance un dé équilibré à six faces. « Pour tous événements $A$ et $B$, on a $P(A \cup B) = P(A) + P(B)$. »`, [
  [T`$A$ : « obtenir 1 ou 2 » ; $B$ : « obtenir 5 ou 6 »`, T`$P(A \cup B) = \dfrac46$ et $P(A) + P(B) = \dfrac26 + \dfrac26$ : l'égalité est vraie pour ces deux événements, qui sont incompatibles.`],
  [T`$A$ : « obtenir un nombre pair » ; $B$ : « obtenir 1 »`, T`$P(A \cup B) = \dfrac46$ et $P(A) + P(B) = \dfrac36 + \dfrac16$ : l'égalité est vraie pour ces deux événements, qui sont incompatibles.`],
  [T`$A$ : « obtenir un nombre pair » ; $B$ : « obtenir un multiple de 3 »`, T`$A \cup B$ contient 2, 3, 4 et 6 : $P(A \cup B) = \dfrac46$, alors que $P(A) + P(B) = \dfrac36 + \dfrac26 = \dfrac56$. L'égalité est fausse : l'issue 6, commune à $A$ et à $B$, est comptée deux fois.`, B],
  [T`$A$ : « obtenir 1 » ; $B$ : « obtenir 7 »`, T`$B$ est impossible : $P(A \cup B) = \dfrac16 = \dfrac16 + 0$. L'égalité est vraie pour ces deux événements.`] ],
  T`$P(A \cup B) = P(A) + P(B) - P(A \cap B)$. On ne peut ajouter les probabilités que lorsque $A$ et $B$ sont incompatibles.`),
contre('sec-meme-norme', 'seconde', '', 's-10', 'Même norme donc égaux', T`Dans un repère orthonormé : « Deux vecteurs de même norme sont égaux. »`, [
  [T`$\vec u(3\,;\,4)$ et $\vec v(3\,;\,4)$`, T`Les deux vecteurs ont la même norme, 5, et sont égaux.` + CV],
  [T`$\vec u(3\,;\,4)$ et $\vec v(4\,;\,3)$`, T`Les deux normes valent $\sqrt{9 + 16} = 5$, mais les coordonnées diffèrent : les vecteurs ne sont pas égaux. L'hypothèse est vraie, la conclusion fausse.`, B],
  [T`$\vec u(1\,;\,0)$ et $\vec v(2\,;\,0)$`, T`Les normes valent 1 et 2 : elles sont différentes.` + HF],
  [T`$\vec u(0\,;\,0)$ et $\vec v(0\,;\,0)$`, T`Les deux vecteurs sont nuls : même norme, et ils sont égaux.` + CV] ],
  T`Deux vecteurs sont égaux quand ils ont la même direction, le même sens <em>et</em> la même norme. La norme seule ne retient que la longueur : les représentants d'origine $O$ de tous les vecteurs de norme 5 ont leur extrémité sur un même cercle.`),
contre('sec-affine-double', 'seconde', '', 's-09', 'f(2x) = 2f(x)', T`« Pour toute fonction affine $f$ et tout réel $x$, on a $f(2x) = 2f(x)$. »`, [
  [T`$f : x \mapsto 3x$`, T`$f(2x) = 6x = 2 \times 3x$ : l'égalité est vraie pour cette fonction, qui est linéaire.`],
  [T`$f : x \mapsto -x$`, T`$f(2x) = -2x = 2 \times (-x)$ : l'égalité est vraie pour cette fonction, qui est linéaire.`],
  [T`$f : x \mapsto 2x + 1$`, T`$f(2x) = 4x + 1$, alors que $2f(x) = 4x + 2$ : ces deux nombres diffèrent pour tout $x$. L'égalité est fausse pour cette fonction.`, B],
  [T`$f : x \mapsto 0$`, T`$f(2x) = 0 = 2 \times 0$ : l'égalité est vraie pour la fonction nulle, qui est linéaire.`] ],
  T`Doubler la variable double l'image pour les fonctions linéaires, $x \mapsto mx$ : c'est la proportionnalité. Dès que l'ordonnée à l'origine $p$ n'est pas nulle, $f(2x) = 2mx + p$ et $2f(x) = 2mx + 2p$ diffèrent.`),
contre('sec-produit-nul', 'seconde', '', 's-04', 'Produit nul, facteurs nuls', T`« Soit $a$ et $b$ deux réels. Si $ab = 0$, alors $a = 0$ et $b = 0$. »`, [
  [T`$a = 0$, $b = 0$`, T`$ab = 0$, et les deux nombres sont nuls.` + CV],
  [T`$a = 0$, $b = 5$`, T`$ab = 0$, et pourtant $b$ n'est pas nul : l'hypothèse est vraie, la conclusion fausse.`, B],
  [T`$a = 2$, $b = 3$`, T`$ab = 6$ n'est pas nul.` + HF],
  [T`$a = 1$, $b = -1$`, T`$ab = -1$ n'est pas nul.` + HF] ],
  T`Un produit est nul si et seulement si l'<em>un au moins</em> de ses facteurs est nul : « $a = 0$ ou $b = 0$ », et non « $a = 0$ et $b = 0$ ». En mathématiques, le « ou » n'exclut pas que les deux soient vrais.`),
contre('sec-equidistant', 'seconde', '', 's-05', 'À égale distance donc milieu', T`Dans un repère orthonormé, soit $A(0\,;\,0)$ et $B(4\,;\,0)$. « Si un point $I$ vérifie $IA = IB$, alors $I$ est le milieu de $[AB]$. »`, [
  [T`$I(2\,;\,0)$`, T`$IA = IB = 2$, et $I$ est bien le milieu de $[AB]$.` + CV],
  [T`$I(2\,;\,3)$`, T`$IA = IB = \sqrt{13}$, et pourtant $I$ n'est pas le milieu de $[AB]$, qui est le point $(2\,;\,0)$ : l'hypothèse est vraie, la conclusion fausse.`, B],
  [T`$I(1\,;\,0)$`, T`$IA = 1$ et $IB = 3$ : les distances sont différentes.` + HF],
  [T`$I(4\,;\,4)$`, T`$IA = \sqrt{32}$ et $IB = 4$ : les distances sont différentes.` + HF] ],
  T`Les points à égale distance de $A$ et de $B$ forment la médiatrice de $[AB]$, ici la droite d'équation $x = 2$. Le milieu est le seul de ces points qui soit aligné avec $A$ et $B$.`),
contre('sec-rationnel-decimal', 'seconde', '', 's-01', 'Rationnel donc décimal', T`« Tout nombre rationnel est un nombre décimal. »`, [
  [T`Le nombre $\dfrac14$`, T`$\dfrac14 = 0{,}25$ est rationnel et décimal.` + CV],
  [T`Le nombre $\dfrac7{20}$`, T`$\dfrac7{20} = 0{,}35$ est rationnel et décimal.` + CV],
  [T`Le nombre $\dfrac13$`, T`$\dfrac13$ est rationnel, comme quotient de deux entiers, mais il n'est pas décimal : son écriture décimale $0{,}333\ldots$ ne s'arrête pas. L'hypothèse est vraie, la conclusion fausse.`, B],
  [T`Le nombre $\sqrt2$`, T`$\sqrt2$ n'est pas rationnel.` + HF] ],
  T`Les ensembles de nombres sont emboîtés dans un seul sens : tout décimal est rationnel, mais un rationnel n'est décimal que si sa fraction irréductible a un dénominateur dont les seuls facteurs premiers sont 2 et 5.`),
// ---------- Première ----------
contre('carre-grand', 'premiere', '', 'p-01', 'x² > 4 donc x > 2', T`« Si un réel $x$ vérifie $x^2 > 4$, alors $x > 2$. »`, [
  [T`$x = 3$`, T`$3^2 = 9 > 4$ et $3 > 2$.` + CV],
  [T`$x = -3$`, T`$(-3)^2 = 9 > 4$, et pourtant $-3$ n'est pas supérieur à 2 : l'hypothèse est vraie, la conclusion fausse.`, B],
  [T`$x = 1$`, T`$1^2 = 1$ n'est pas supérieur à 4.` + HF],
  [T`$x = 2$`, T`$2^2 = 4$ n'est pas strictement supérieur à 4.` + HF] ],
  T`$x^2 > 4$ équivaut à $x > 2$ ou $x < -2$. Un contre-exemple à « si $H$ alors $C$ » vérifie $H$ sans vérifier $C$.`),
contre('croissante-infini', 'premiere', '', 'p-02', 'Croissante donc de limite infinie', T`« Toute suite croissante finit par dépasser n'importe quel nombre. »`, [
  [T`$u_n = n$`, T`Cette suite est croissante et dépasse n'importe quel nombre.` + CV],
  [T`$u_n = 1 - \dfrac{1}{n + 1}$`, T`Cette suite est croissante, puisque l'on retranche de moins en moins, mais tous ses termes sont inférieurs à 1 : elle ne dépasse jamais 1.`, B],
  [T`$u_n = (-1)^n$`, T`Cette suite n'est pas croissante : elle passe de 1 à $-1$.` + HF],
  [T`$u_n = -n$`, T`Cette suite est décroissante.` + HF] ],
  T`Une suite croissante peut être majorée : elle se rapproche alors d'un plafond sans le dépasser. Croissante ne veut pas dire « qui tend vers $+\infty$ ».`),
contre('derivee-nulle', 'premiere', '', 'p-04', 'Dérivée nulle donc extremum', T`« Si $f'(a) = 0$, alors $f$ admet un extremum local en $a$. »`, [
  [T`$f(x) = x^2$ et $a = 0$`, T`$f'(0) = 0$ et $f$ a un minimum en 0.` + CV],
  [T`$f(x) = x^3$ et $a = 0$`, T`$f'(0) = 0$, mais $f$ est strictement croissante : $f(x) < 0$ avant 0 et $f(x) > 0$ après, il n'y a pas d'extremum.`, B],
  [T`$f(x) = x$ et $a = 0$`, T`$f'(0) = 1$ n'est pas nul.` + HF],
  [T`$f(x) = x^2 - 2x$ et $a = 1$`, T`$f'(1) = 0$ et $f$ a un minimum en 1.` + CV] ],
  T`C'est le changement de signe de la dérivée qui garantit un extremum : il suffit que $f'$ s'annule en $a$ en changeant de signe. En 0, la dérivée $3x^2$ de $x^3$ s'annule sans changer de signe.`),
contre('carre-plus-grand', 'premiere', '', 'p-01', 'Un carré plus grand que le nombre', T`« Le carré d'un réel positif est toujours supérieur ou égal à ce réel. »`, [
  [T`$x = 2$`, T`$2^2 = 4 \geqslant 2$ : l'énoncé est vérifié pour ce nombre.`],
  [T`$x = 1$`, T`$1^2 = 1 \geqslant 1$ : l'énoncé est vérifié pour ce nombre.`],
  [T`$x = \dfrac12$`, T`$\left(\dfrac12\right)^2 = \dfrac14$, qui est plus petit que $\dfrac12$.`, B],
  [T`$x = 10$`, T`$10^2 = 100 \geqslant 10$ : l'énoncé est vérifié pour ce nombre.`] ],
  T`Pour $0 < x < 1$, on a $x^2 < x$ : multiplier par un nombre inférieur à 1 fait diminuer. Tester seulement des entiers ne révèle pas ce cas.`),
contre('incompatibles', 'premiere', '', 'p-05', 'Incompatibles donc indépendants', T`On lance un dé équilibré. « Deux événements incompatibles sont indépendants. »`, [
  [T`$A$ : « le résultat est pair » ; $B$ : « le résultat est impair »`, T`Ces événements sont incompatibles, donc $P(A \cap B) = 0$, alors que $P(A)\,P(B) = \dfrac14$ : ils ne sont pas indépendants.`, B],
  [T`$A$ : « le résultat est pair » ; $B$ : « le résultat est 1 ou 2 »`, T`Ces événements ne sont pas incompatibles : le résultat 2 réalise les deux.` + HF],
  [T`$A$ : « le résultat est 1 » ; $B$ : « le résultat est 1 ou 2 »`, T`Ces événements ne sont pas incompatibles : le résultat 1 réalise les deux.` + HF],
  [T`$A$ : « le résultat est 7 » ; $B$ : « le résultat est pair »`, T`$A$ est impossible : les événements sont incompatibles, et $P(A \cap B) = 0 = P(A)\,P(B)$.` + CV] ],
  T`Deux événements incompatibles de probabilités non nulles ne sont jamais indépendants : si l'un se produit, l'autre est exclu.`),
contre('carre-somme', 'premiere', '', 'p-01', 'Le carré d\'une somme', T`« Pour tous réels $a$ et $b$, $(a + b)^2 = a^2 + b^2$. »`, [
  [T`$a = 0$ et $b = 5$`, T`$(0 + 5)^2 = 25$ et $0^2 + 5^2 = 25$ : l'égalité est vraie pour ces nombres.`],
  [T`$a = 1$ et $b = 1$`, T`$(1 + 1)^2 = 4$, alors que $1^2 + 1^2 = 2$.`, B],
  [T`$a = 3$ et $b = 0$`, T`$(3 + 0)^2 = 9$ et $3^2 + 0^2 = 9$ : l'égalité est vraie pour ces nombres.`],
  [T`$a = 0$ et $b = 0$`, T`Les deux membres valent 0 : l'égalité est vraie pour ces nombres.`] ],
  T`$(a + b)^2 = a^2 + 2ab + b^2$ : l'égalité proposée n'est vraie que si $ab = 0$. Un exemple avec un zéro ne teste rien.`),
contre('scalaire-simplifier', 'premiere', '', 'p-07', 'Simplifier un produit scalaire', T`« Si $\vec u$ n'est pas nul et si $\vec u \cdot \vec v = \vec u \cdot \vec w$, alors $\vec v = \vec w$. »`, [
  [T`$\vec u(1 ; 0)$, $\vec v(0 ; 1)$, $\vec w(0 ; 2)$`, T`$\vec u \cdot \vec v = 0$ et $\vec u \cdot \vec w = 0$, alors que $\vec v \neq \vec w$.`, B],
  [T`$\vec u(1 ; 0)$, $\vec v(2 ; 1)$, $\vec w(2 ; 1)$`, T`Les produits scalaires sont égaux, et $\vec v = \vec w$.` + CV],
  [T`$\vec u(1 ; 1)$, $\vec v(1 ; 0)$, $\vec w(0 ; 0)$`, T`$\vec u \cdot \vec v = 1$ et $\vec u \cdot \vec w = 0$ : les produits scalaires sont différents.` + HF],
  [T`$\vec u(1 ; 0)$, $\vec v(1 ; 2)$, $\vec w(3 ; 2)$`, T`$\vec u \cdot \vec v = 1$ et $\vec u \cdot \vec w = 3$ : les produits scalaires sont différents.` + HF] ],
  T`$\vec u \cdot \vec v = \vec u \cdot \vec w$ signifie que $\vec v - \vec w$ est orthogonal à $\vec u$, pas qu'il est nul.`),
contre('racine-somme', 'premiere', '', 'p-01', 'La racine d\'une somme', T`« Pour tous réels positifs $a$ et $b$, $\sqrt{a + b} = \sqrt a + \sqrt b$. »`, [
  [T`$a = 0$ et $b = 4$`, T`Les deux membres valent 2 : l'égalité est vraie pour ces nombres.`],
  [T`$a = 9$ et $b = 16$`, T`$\sqrt{25} = 5$, alors que $\sqrt9 + \sqrt{16} = 7$.`, B],
  [T`$a = 0$ et $b = 0$`, T`Les deux membres valent 0 : l'égalité est vraie pour ces nombres.`],
  [T`$a = 1$ et $b = 0$`, T`Les deux membres valent 1 : l'égalité est vraie pour ces nombres.`] ],
  T`La racine carrée est compatible avec le produit, $\sqrt{ab} = \sqrt a\,\sqrt b$, pas avec la somme. L'égalité proposée n'a lieu que si $a = 0$ ou $b = 0$.`),
contre('sinus-nul', 'premiere', '', 'p-06', 'sin x = 0 donc cos x = 1', T`« Si $\sin x = 0$, alors $\cos x = 1$. »`, [
  [T`$x = 0$`, T`$\sin 0 = 0$ et $\cos 0 = 1$.` + CV],
  [T`$x = 2\pi$`, T`$\sin(2\pi) = 0$ et $\cos(2\pi) = 1$.` + CV],
  [T`$x = \pi$`, T`$\sin\pi = 0$, et pourtant $\cos\pi = -1$.`, B],
  [T`$x = \dfrac{\pi}{2}$`, T`$\sin\dfrac{\pi}{2} = 1$ n'est pas nul.` + HF] ],
  T`Sur le cercle trigonométrique, deux points ont une ordonnée nulle : ceux d'abscisses 1 et $-1$. Si $\sin x = 0$, alors $\cos x = 1$ ou $\cos x = -1$.`),
// ---------- Terminale ----------
contre('bornee-convergente', 'terminale', '', 't-01', 'Bornée donc convergente', T`« Toute suite bornée converge. »`, [
  [T`$u_n = (-1)^n$`, T`Cette suite est bornée par $-1$ et 1, et elle n'a pas de limite : elle oscille entre ces deux valeurs.`, B],
  [T`$u_n = \dfrac1n$`, T`Cette suite est bornée et converge vers 0.` + CV],
  [T`$u_n = n$`, T`Cette suite n'est pas bornée.` + HF],
  [T`$u_n = \dfrac{(-1)^n}{n}$`, T`Cette suite est bornée et converge vers 0.` + CV] ],
  T`Convergente entraîne bornée ; la réciproque est fausse. Ce qui est vrai : toute suite monotone et bornée converge.`),
contre('continue-derivable', 'terminale', '', 't-03', 'Continue donc dérivable', T`« Toute fonction continue en $a$ est dérivable en $a$. »`, [
  [T`$f(x) = |x|$ et $a = 0$`, T`Cette fonction est continue en 0, mais ses taux de variation valent $-1$ à gauche et 1 à droite : elle n'est pas dérivable en 0.`, B],
  [T`$f(x) = x^2$ et $a = 0$`, T`Cette fonction est continue et dérivable en 0.` + CV],
  [T`$f(x) = \dfrac1x$ et $a = 0$`, T`Cette fonction n'est pas définie en 0, donc pas continue en 0.` + HF],
  [T`$f(x) = e^x$ et $a = 0$`, T`Cette fonction est continue et dérivable en 0.` + CV] ],
  T`Dérivable entraîne continue ; la réciproque est fausse. Un point anguleux est le cas type d'une fonction continue non dérivable.`),
contre('infini-fois-zero', 'terminale', '', 't-01', 'L\'infini fois zéro', T`« Si $(u_n)$ tend vers $+\infty$ et $(v_n)$ tend vers 0, alors $(u_n v_n)$ tend vers 0. »`, [
  [T`$u_n = n$ et $v_n = \dfrac{1}{n^2}$`, T`Le produit vaut $\dfrac1n$, qui tend vers 0.` + CV],
  [T`$u_n = n^2$ et $v_n = \dfrac1n$`, T`Les hypothèses sont vérifiées, mais le produit vaut $n$, qui tend vers $+\infty$.`, B],
  [T`$u_n = n$ et $v_n = 1$`, T`La suite $(v_n)$ ne tend pas vers 0.` + HF],
  [T`$u_n = 1$ et $v_n = \dfrac1n$`, T`La suite $(u_n)$ ne tend pas vers $+\infty$.` + HF] ],
  T`« $\infty \times 0$ » est une forme indéterminée : selon les suites, le produit peut tendre vers 0, vers l'infini, ou vers n'importe quel réel.`),
contre('inflexion', 'terminale', '', 't-03', 'Dérivée seconde nulle donc inflexion', T`« Si $f''(a) = 0$, alors la courbe de $f$ a un point d'inflexion en $a$. »`, [
  [T`$f(x) = x^3$ et $a = 0$`, T`$f''(0) = 0$ et la courbe a bien un point d'inflexion en 0.` + CV],
  [T`$f(x) = x^4$ et $a = 0$`, T`$f''(x) = 12x^2$ s'annule en 0 sans changer de signe : la fonction est convexe, il n'y a pas de point d'inflexion.`, B],
  [T`$f(x) = x^2$ et $a = 0$`, T`$f''(0) = 2$ n'est pas nul.` + HF],
  [T`$f(x) = e^x$ et $a = 0$`, T`$f''(0) = 1$ n'est pas nul.` + HF] ],
  T`Il faut que $f''$ s'annule en changeant de signe : c'est le changement de convexité qui fait le point d'inflexion.`),
contre('integrale-nulle', 'terminale', '', 't-06', 'Intégrale nulle donc fonction nulle', T`« Si $\displaystyle\int_a^b f(x)\,dx = 0$, alors $f$ est nulle sur $[a, b]$. »`, [
  [T`$f(x) = x$ sur $[-1, 1]$`, T`L'intégrale est nulle, les aires de part et d'autre de 0 se compensant, et $f$ n'est pas la fonction nulle.`, B],
  [T`$f(x) = 0$ sur $[0, 1]$`, T`L'intégrale est nulle et la fonction aussi.` + CV],
  [T`$f(x) = x$ sur $[0, 1]$`, T`L'intégrale vaut $\dfrac12$.` + HF],
  [T`$f(x) = x^2$ sur $[-1, 1]$`, T`L'intégrale vaut $\dfrac23$.` + HF] ],
  T`L'énoncé devient vrai pour une fonction continue et positive. Sans la positivité, des aires de signes contraires peuvent se compenser.`),
contre('ln-somme', 'terminale', '', 't-05', 'Le logarithme d\'une somme', T`« Pour tous réels $a > 0$ et $b > 0$, $\ln(a + b) = \ln a + \ln b$. »`, [
  [T`$a = 2$ et $b = 2$`, T`$\ln 4 = 2\ln 2$ : l'égalité est vraie pour ces nombres, parce que $2 + 2 = 2 \times 2$.`],
  [T`$a = 1$ et $b = 1$`, T`$\ln 2 \approx 0{,}69$, alors que $\ln 1 + \ln 1 = 0$.`, B],
  [T`$a = 3$ et $b = 1{,}5$`, T`$3 + 1{,}5 = 4{,}5 = 3 \times 1{,}5$ : les deux membres valent $\ln 4{,}5$, l'égalité est vraie pour ces nombres.`],
  [T`$a = 4$ et $b = \dfrac43$`, T`$4 + \dfrac43 = \dfrac{16}{3} = 4 \times \dfrac43$ : l'égalité est vraie pour ces nombres.`] ],
  T`$\ln a + \ln b = \ln(ab)$ : l'égalité proposée n'a lieu que si $a + b = ab$. Des exemples bien choisis peuvent donner raison à une formule fausse ; un seul contre-exemple la réfute.`),
contre('non-paralleles', 'terminale', '', 't-04', 'Non parallèles donc sécantes', T`Dans un repère $(O ; \vec i, \vec j, \vec k)$ de l'espace : « Deux droites qui ne sont pas parallèles sont sécantes. »`, [
  [T`La droite $(O ; \vec i)$ et la droite passant par $A(0 ; 0 ; 1)$ dirigée par $\vec j$`, T`Elles ne sont pas parallèles, et n'ont aucun point commun : les points de l'une ont pour cote 0, ceux de l'autre pour cote 1.`, B],
  [T`La droite $(O ; \vec i)$ et la droite $(O ; \vec j)$`, T`Elles ne sont pas parallèles et se coupent en $O$.` + CV],
  [T`La droite $(O ; \vec i)$ et la droite passant par $B(0 ; 1 ; 0)$ dirigée par $\vec i$`, T`Ces deux droites sont parallèles.` + HF],
  [T`La droite $(O ; \vec i)$ et la droite passant par $C(1 ; 0 ; 0)$ dirigée par $\vec k$`, T`Elles ne sont pas parallèles et se coupent en $C$.` + CV] ],
  T`Dans l'espace, deux droites peuvent être non coplanaires : ni parallèles, ni sécantes.`),
contre('meme-loi', 'terminale', '', 't-02', 'Même loi donc égales', T`« Deux variables aléatoires qui ont la même loi sont égales. »`, [
  [T`$X$ est le résultat d'un dé, et $Y = X$`, T`Les deux variables ont la même loi et sont égales.` + CV],
  [T`$X$ vaut 0 ou 1 selon le résultat d'une pièce équilibrée, et $Y = 1 - X$`, T`$X$ et $Y$ valent chacune 0 ou 1 avec la probabilité $\dfrac12$ : même loi. Pourtant elles ne sont jamais égales.`, B],
  [T`$X$ est le résultat d'un dé, et $Y = 2X$`, T`$Y$ prend les valeurs 2, 4, …, 12 : les deux variables n'ont pas la même loi.` + HF],
  [T`$X$ est le résultat d'un dé, et $Y = X + 1$`, T`$Y$ prend les valeurs 2 à 7 : les deux variables n'ont pas la même loi.` + HF] ],
  T`La loi d'une variable décrit les probabilités de ses valeurs, pas la variable elle-même. Deux lancers d'un même dé ont la même loi sans donner le même résultat.`),
contre('tend-vers-zero', 'terminale', '', 't-01', 'Tend vers 0 donc décroît', T`« Une suite de réels positifs qui tend vers 0 est décroissante à partir d'un certain rang. »`, [
  [T`$u_n = \dfrac1n$`, T`Cette suite tend vers 0 et elle est décroissante.` + CV],
  [T`$u_n = \dfrac{2 + (-1)^n}{n}$`, T`Cette suite est positive et tend vers 0, mais $u_{2n} = \dfrac{3}{2n}$ est plus grand que $u_{2n-1} = \dfrac{1}{2n-1}$ : elle remonte à chaque rang pair.`, B],
  [T`$u_n = \dfrac{1}{2^n}$`, T`Cette suite tend vers 0 et elle est décroissante.` + CV],
  [T`$u_n = n$`, T`Cette suite ne tend pas vers 0.` + HF] ],
  T`Avoir une limite ne dit rien du sens de variation : une suite peut converger en oscillant.`),
// ---------- Maths expertes ----------
contre('divise-produit', 'expertes', '', 'me-07', 'Diviser un produit', T`« Si un entier $a$ divise un produit $bc$, alors $a$ divise $b$ ou $a$ divise $c$. »`, [
  [T`$a = 6$, $b = 4$, $c = 9$`, T`6 divise 36, mais ne divise ni 4 ni 9.`, B],
  [T`$a = 3$, $b = 4$, $c = 9$`, T`3 divise 36 et divise 9.` + CV],
  [T`$a = 5$, $b = 4$, $c = 9$`, T`5 ne divise pas 36.` + HF],
  [T`$a = 4$, $b = 4$, $c = 9$`, T`4 divise 36 et divise 4.` + CV] ],
  T`L'énoncé est vrai quand $a$ est premier (lemme d'Euclide), ou quand $a$ est premier avec $b$ (théorème de Gauss).`),
contre('euler-41', 'expertes', '', 'me-01', 'Une formule à nombres premiers', T`« Pour tout entier naturel $n$, le nombre $n^2 + n + 41$ est premier. »`, [
  [T`$n = 0$`, T`On obtient 41, qui est premier : l'énoncé est vérifié pour cet entier.`],
  [T`$n = 10$`, T`On obtient 151, qui est premier : l'énoncé est vérifié pour cet entier.`],
  [T`$n = 40$`, T`On obtient $1600 + 40 + 41 = 1681 = 41^2$, qui n'est pas premier.`, B],
  [T`$n = 39$`, T`On obtient 1601, qui est premier : l'énoncé est vérifié pour cet entier.`] ],
  T`Ce polynôme d'Euler donne un nombre premier pour tous les entiers de 0 à 39 : quarante vérifications ne font pas une démonstration.`),
contre('carres-congrus', 'expertes', '', 'me-04', 'Carrés congrus', T`« Si $a^2 \equiv b^2 \pmod n$, alors $a \equiv b \pmod n$. »`, [
  [T`$a = 3$, $b = 1$, $n = 8$`, T`$9 \equiv 1 \pmod 8$, alors que 3 et 1 ne sont pas congrus modulo 8.`, B],
  [T`$a = 5$, $b = 1$, $n = 4$`, T`$25 \equiv 1 \pmod 4$, et $5 \equiv 1 \pmod 4$.` + CV],
  [T`$a = 7$, $b = 2$, $n = 5$`, T`$49 \equiv 4 \pmod 5$, et $7 \equiv 2 \pmod 5$.` + CV],
  [T`$a = 3$, $b = 2$, $n = 7$`, T`$9 \equiv 2$ et $4 \equiv 4 \pmod 7$ : les carrés ne sont pas congrus.` + HF] ],
  T`On peut élever une congruence au carré, pas en prendre la racine.`),
contre('module-somme', 'expertes', '', 'me-02', 'Le module d\'une somme', T`« Pour tous nombres complexes $z$ et $z'$, $|z + z'| = |z| + |z'|$. »`, [
  [T`$z = 1$ et $z' = 2$`, T`$|3| = 3 = 1 + 2$ : l'égalité est vraie pour ces nombres.`],
  [T`$z = i$ et $z' = 3i$`, T`$|4i| = 4 = 1 + 3$ : l'égalité est vraie pour ces nombres.`],
  [T`$z = 1$ et $z' = i$`, T`$|1 + i| = \sqrt2$, alors que $|1| + |i| = 2$.`, B],
  [T`$z = 0$ et $z' = 5$`, T`Les deux membres valent 5 : l'égalité est vraie pour ces nombres.`] ],
  T`$|z + z'| \leqslant |z| + |z'|$, avec égalité quand les points images sont sur une même demi-droite issue de l'origine.`),
contre('matrices-commutent', 'expertes', '', 'me-03', 'Le produit de matrices commute', T`« Pour toutes matrices carrées $A$ et $B$ d'ordre 2, $AB = BA$. »`, [
  [T`$A = I_2$ et $B = \begin{pmatrix} 1 & 2 \\ 3 & 4 \end{pmatrix}$`, T`$AB = B = BA$ : l'égalité est vraie pour ces matrices.`],
  [T`$A = \begin{pmatrix} 0 & 1 \\ 0 & 0 \end{pmatrix}$ et $B = \begin{pmatrix} 0 & 0 \\ 1 & 0 \end{pmatrix}$`, T`$AB = \begin{pmatrix} 1 & 0 \\ 0 & 0 \end{pmatrix}$, alors que $BA = \begin{pmatrix} 0 & 0 \\ 0 & 1 \end{pmatrix}$.`, B],
  [T`$A = 2I_2$ et $B = \begin{pmatrix} 1 & 2 \\ 3 & 4 \end{pmatrix}$`, T`$AB = 2B = BA$ : l'égalité est vraie pour ces matrices.`],
  [T`$A = B = \begin{pmatrix} 1 & 2 \\ 3 & 4 \end{pmatrix}$`, T`$AB = A^2 = BA$ : l'égalité est vraie pour ces matrices.`] ],
  T`Le produit matriciel n'est pas commutatif. Une matrice commute toujours avec elle-même, avec l'identité et avec ses multiples.`),
contre('chaine-eulerienne', 'expertes', '', 'me-06', 'Connexe donc eulérien', T`« Tout graphe connexe admet une chaîne eulérienne. »`, [
  [T`Un triangle : trois sommets reliés deux à deux`, T`Tous les sommets sont de degré 2 : le graphe admet un cycle eulérien.` + CV],
  [T`Une chaîne de trois sommets $A$ — $B$ — $C$`, T`La chaîne $A$, $B$, $C$ emprunte chaque arête une fois.` + CV],
  [T`Le graphe complet à quatre sommets, où chaque sommet est relié aux trois autres`, T`Il est connexe, mais ses quatre sommets sont de degré 3 : il y a plus de deux sommets de degré impair, donc pas de chaîne eulérienne.`, B],
  [T`Un carré $ABCD$ avec sa diagonale $[AC]$`, T`Deux sommets seulement, $A$ et $C$, sont de degré impair : il existe une chaîne eulérienne de $A$ à $C$.` + CV] ],
  T`Théorème d'Euler, admis ici (il complète le chapitre sur les graphes) : un graphe connexe admet une chaîne eulérienne si et seulement s'il a zéro ou deux sommets de degré impair.`),
contre('carre-reel', 'expertes', '', 'me-02', 'Carré réel donc nombre réel', T`« Si le carré d'un nombre complexe $z$ est réel, alors $z$ est réel. »`, [
  [T`$z = 2$`, T`$z^2 = 4$ est réel et $z$ aussi.` + CV],
  [T`$z = i$`, T`$z^2 = -1$ est réel, alors que $i$ ne l'est pas.`, B],
  [T`$z = 1 + i$`, T`$z^2 = 2i$ n'est pas réel.` + HF],
  [T`$z = -3$`, T`$z^2 = 9$ est réel et $z$ aussi.` + CV] ],
  T`$z^2$ est réel si et seulement si $z$ est réel ou imaginaire pur.`),
contre('mersenne', 'expertes', '', 'me-01', 'Nombres de Mersenne', T`« Si $p$ est un nombre premier, alors $2^p - 1$ est premier. »`, [
  [T`$p = 3$`, T`$2^3 - 1 = 7$ est premier.` + CV],
  [T`$p = 5$`, T`$2^5 - 1 = 31$ est premier.` + CV],
  [T`$p = 7$`, T`$2^7 - 1 = 127$ est premier.` + CV],
  [T`$p = 11$`, T`$2^{11} - 1 = 2047 = 23 \times 89$ n'est pas premier.`, B] ],
  T`C'est la réciproque qui est vraie : si $2^n - 1$ est premier, alors $n$ est premier.`),
// ---------- Maths Sup : fondements ----------
contre('composee-g', 'sup', F, 'ma-02', 'g ∘ f injective donc g injective', T`« Si $g \circ f$ est injective, alors $g$ est injective. »`, [
  [T`$f : \{0\} \to \{0, 1\}$, $f(0) = 0$, et $g : \{0, 1\} \to \{0\}$`, T`$g \circ f$ part d'un ensemble à un élément, elle est injective ; $g$ ne l'est pas, puisque $g(0) = g(1)$.`, B],
  [T`$f = \mathrm{id}_{\mathbb{R}}$ et $g = \mathrm{id}_{\mathbb{R}}$`, T`$g \circ f$ est injective et $g$ aussi.` + CV],
  [T`$f = \mathrm{id}_{\mathbb{R}}$ et $g : x \mapsto x^2$ sur $\mathbb{R}$`, T`$g \circ f = g$ n'est pas injective.` + HF],
  [T`$f : x \mapsto 2x$ et $g : x \mapsto x + 1$ sur $\mathbb{R}$`, T`$g \circ f$ est injective et $g$ aussi.` + CV] ],
  T`Si $g \circ f$ est injective, c'est $f$ qui l'est. L'injectivité de $g \circ f$ ne renseigne sur $g$ que sur l'image de $f$.`),
contre('image-intersection', 'sup', F, 'ma-02', 'Image d\'une intersection', T`« Pour toute application $f$ et toutes parties $A$ et $B$, $f(A \cap B) = f(A) \cap f(B)$. »`, [
  [T`$f : x \mapsto x^2$, $A = [-1, 0]$, $B = [0, 1]$`, T`$f(A \cap B) = \{0\}$, alors que $f(A) \cap f(B) = [0, 1]$.`, B],
  [T`$f : x \mapsto x^2$, $A = [0, 1]$, $B = [0, 2]$`, T`$f(A \cap B) = [0, 1]$ et $f(A) \cap f(B) = [0, 1] \cap [0, 4] = [0, 1]$ : l'égalité est vraie ici.`],
  [T`$f : x \mapsto 2x$, $A = [-1, 0]$, $B = [0, 1]$`, T`Les deux ensembles valent $\{0\}$ : l'égalité est vraie ici, $f$ étant injective.`],
  [T`$f : x \mapsto x^2$, $A = [1, 2]$, $B = [3, 4]$`, T`Les deux ensembles sont vides : l'égalité est vraie ici.`] ],
  T`On a toujours $f(A \cap B) \subset f(A) \cap f(B)$, avec égalité pour toutes les parties si et seulement si $f$ est injective.`),
contre('reflexive', 'sup', F, 'ma-02', 'Symétrique et transitive donc réflexive', T`« Toute relation symétrique et transitive sur $\mathbb{Z}$ est réflexive. »`, [
  [T`$x \mathrel{\mathcal{R}} y$ si $xy > 0$`, T`Cette relation est symétrique et transitive, mais 0 n'est pas en relation avec lui-même.`, B],
  [T`$x \mathrel{\mathcal{R}} y$ si $x - y$ est pair`, T`Cette relation est symétrique, transitive et réflexive.` + CV],
  [T`$x \mathrel{\mathcal{R}} y$ si $x \leqslant y$`, T`Cette relation n'est pas symétrique.` + HF],
  [T`$x \mathrel{\mathcal{R}} y$ si $x = y + 1$`, T`Cette relation n'est pas symétrique.` + HF] ],
  T`De $x \mathrel{\mathcal{R}} y$ et $y \mathrel{\mathcal{R}} x$ on tire bien $x \mathrel{\mathcal{R}} x$, mais encore faut-il que $x$ soit en relation avec un élément.`),
// ---------- Maths Sup : algèbre ----------
contre('reunion-sous-groupes', 'sup', A, 'ma-11', 'Réunion de sous-groupes', T`« La réunion de deux sous-groupes de $(\mathbb{Z}, +)$ est un sous-groupe. »`, [
  [T`$2\mathbb{Z} \cup 3\mathbb{Z}$`, T`Cette réunion contient 2 et 3, mais pas leur somme 5.`, B],
  [T`$2\mathbb{Z} \cup 4\mathbb{Z}$`, T`Comme $4\mathbb{Z} \subset 2\mathbb{Z}$, la réunion est $2\mathbb{Z}$ : c'est un sous-groupe.`],
  [T`$3\mathbb{Z} \cup \{0\}$`, T`La réunion est $3\mathbb{Z}$ : c'est un sous-groupe.`],
  [T`$6\mathbb{Z} \cup 3\mathbb{Z}$`, T`Comme $6\mathbb{Z} \subset 3\mathbb{Z}$, la réunion est $3\mathbb{Z}$ : c'est un sous-groupe.`] ],
  T`La réunion de deux sous-groupes est un sous-groupe si et seulement si l'un est contenu dans l'autre. C'est l'intersection qui est toujours un sous-groupe.`),
contre('sans-racine', 'sup', A, 'ma-13', 'Sans racine donc irréductible', T`« Un polynôme réel de degré au moins 2 sans racine réelle est irréductible dans $\mathbb{R}[X]$. »`, [
  [T`$X^2 + 1$`, T`Ce polynôme n'a pas de racine réelle et il est irréductible.` + CV],
  [T`$X^4 + 1$`, T`Il n'a pas de racine réelle, mais $X^4 + 1 = (X^2 + \sqrt2\,X + 1)(X^2 - \sqrt2\,X + 1)$.`, B],
  [T`$X^2 - 1$`, T`Ce polynôme a deux racines réelles, 1 et $-1$.` + HF],
  [T`$X^2 + X + 1$`, T`Son discriminant est $-3$ : il n'a pas de racine réelle et il est irréductible.` + CV] ],
  T`Sur un corps quelconque, « sans racine » équivaut à « irréductible » en degrés 2 et 3 seulement. Dans $\mathbb{R}[X]$, les polynômes irréductibles sont ceux de degré 1 et ceux de degré 2 à discriminant strictement négatif.`),
contre('degre-somme', 'sup', A, 'ma-13', 'Degré d\'une somme', T`« Pour tous polynômes non nuls $P$ et $Q$, $\deg(P + Q) = \max(\deg P, \deg Q)$. »`, [
  [T`$P = X^2$ et $Q = X$`, T`$P + Q = X^2 + X$ est de degré 2 : l'égalité est vraie ici.`],
  [T`$P = X + 1$ et $Q = -X$`, T`$P + Q = 1$ est de degré 0, alors que les deux polynômes sont de degré 1.`, B],
  [T`$P = X^3$ et $Q = X^3$`, T`$P + Q = 2X^3$ est de degré 3 : l'égalité est vraie ici.`],
  [T`$P = 1$ et $Q = X$`, T`$P + Q = X + 1$ est de degré 1 : l'égalité est vraie ici.`] ],
  T`$\deg(P + Q) \leqslant \max(\deg P, \deg Q)$, avec égalité dès que les degrés sont différents ; à degrés égaux, les termes dominants peuvent se détruire.`),
contre('anneau-integre', 'sup', A, 'ma-11', 'Produit nul dans un anneau', T`« Dans un anneau commutatif, si $ab = 0$, alors $a = 0$ ou $b = 0$. »`, [
  [T`Dans $\mathbb{Z}/6\mathbb{Z}$ : $a = \overline2$ et $b = \overline3$`, T`$\overline2 \times \overline3 = \overline6 = \overline0$, alors qu'aucune des deux classes n'est nulle.`, B],
  [T`Dans $\mathbb{Z}/5\mathbb{Z}$ : $a = \overline2$ et $b = \overline3$`, T`$\overline2 \times \overline3 = \overline6 = \overline1$ : le produit n'est pas nul.` + HF],
  [T`Dans $\mathbb{Z}$ : $a = 0$ et $b = 7$`, T`Le produit est nul et $a = 0$.` + CV],
  [T`Dans $\mathbb{Z}/6\mathbb{Z}$ : $a = \overline5$ et $b = \overline5$`, T`$\overline5 \times \overline5 = \overline{25} = \overline1$ : le produit n'est pas nul.` + HF] ],
  T`Un anneau où la règle du produit nul est vraie est dit intègre. Pour $n \geqslant 2$, $\mathbb{Z}/n\mathbb{Z}$ est intègre si et seulement si $n$ est premier.`),
// ---------- Maths Sup : algèbre linéaire ----------
contre('deux-a-deux', 'sup', L, 'ma-14', 'Deux à deux non colinéaires donc libre', T`« Une famille de vecteurs deux à deux non colinéaires est libre. »`, [
  [T`$\bigl((1, 0), (0, 1), (1, 1)\bigr)$ dans $\mathbb{R}^2$`, T`Aucun de ces vecteurs n'est multiple d'un autre, mais le troisième est la somme des deux premiers : la famille est liée.`, B],
  [T`$\bigl((1, 0), (0, 1)\bigr)$ dans $\mathbb{R}^2$`, T`Ces deux vecteurs ne sont pas colinéaires et la famille est libre.` + CV],
  [T`$\bigl((1, 0), (2, 0), (0, 1)\bigr)$ dans $\mathbb{R}^2$`, T`Les deux premiers vecteurs sont colinéaires.` + HF],
  [T`$\bigl((1, 0, 0), (0, 1, 0), (0, 0, 1)\bigr)$ dans $\mathbb{R}^3$`, T`Ces vecteurs sont deux à deux non colinéaires et la famille est libre.` + CV] ],
  T`« Deux à deux non colinéaires » équivaut à « libre » seulement pour deux vecteurs. Au-delà, il faut qu'aucun vecteur ne soit combinaison linéaire de tous les autres.`),
contre('injectif-surjectif', 'sup', L, 'ma-15', 'Injectif donc surjectif', T`« Tout endomorphisme injectif est surjectif. »`, [
  [T`$P \mapsto XP$ sur $\mathbb{R}[X]$`, T`Cet endomorphisme est injectif, mais le polynôme constant 1 n'a pas d'antécédent.`, B],
  [T`$P \mapsto P'$ sur $\mathbb{R}[X]$`, T`La dérivation n'est pas injective : elle annule les constantes.` + HF],
  [T`$(x, y) \mapsto (y, x)$ sur $\mathbb{R}^2$`, T`Cet endomorphisme est injectif et surjectif.` + CV],
  [T`$(x, y) \mapsto (x, 0)$ sur $\mathbb{R}^2$`, T`Cet endomorphisme n'est pas injectif : il annule $(0, 1)$.` + HF] ],
  T`L'énoncé est vrai en dimension finie, par le théorème du rang. En dimension infinie, il est faux.`),
contre('det-somme', 'sup', L, 'ma-17', 'Déterminant d\'une somme', T`« Pour toutes matrices $A$ et $B$ de $\mathcal{M}_2(\mathbb{R})$, $\det(A + B) = \det A + \det B$. »`, [
  [T`$A = I_2$ et $B = I_2$`, T`$\det(2I_2) = 4$, alors que $\det I_2 + \det I_2 = 2$.`, B],
  [T`$A = 0$ et $B = \begin{pmatrix} 1 & 2 \\ 3 & 4 \end{pmatrix}$`, T`Les deux membres valent $\det B = -2$ : l'égalité est vraie ici.`],
  [T`$A = \begin{pmatrix} 1 & 0 \\ 0 & 0 \end{pmatrix}$ et $B = \begin{pmatrix} 2 & 0 \\ 0 & 0 \end{pmatrix}$`, T`Les trois déterminants sont nuls : l'égalité est vraie ici.`],
  [T`$A = \begin{pmatrix} 1 & 0 \\ 0 & 0 \end{pmatrix}$ et $B = \begin{pmatrix} 0 & 1 \\ 0 & 0 \end{pmatrix}$`, T`$A + B = \begin{pmatrix} 1 & 1 \\ 0 & 0 \end{pmatrix}$ : les trois déterminants sont nuls, l'égalité est vraie ici.`] ],
  T`Le déterminant est multiplicatif, $\det(AB) = \det A \det B$, pas additif.`),
contre('dimensions', 'sup', L, 'ma-15', 'Dimensions complémentaires donc supplémentaires', T`Dans $\mathbb{R}^2$ : « Si $\dim F + \dim G = 2$, alors $F$ et $G$ sont supplémentaires. »`, [
  [T`$F = G$, tous deux égaux à l'axe des abscisses`, T`La somme des dimensions vaut 2, mais $F + G$ n'est qu'une droite.`, B],
  [T`$F$ l'axe des abscisses, $G$ l'axe des ordonnées`, T`La somme des dimensions vaut 2 et les deux axes sont supplémentaires.` + CV],
  [T`$F = \{0\}$ et $G = \mathbb{R}^2$`, T`La somme des dimensions vaut 2 et ces sous-espaces sont supplémentaires.` + CV],
  [T`$F$ l'axe des abscisses et $G = \mathbb{R}^2$`, T`La somme des dimensions vaut 3.` + HF] ],
  T`Il faut en plus $F \cap G = \{0\}$. La condition sur les dimensions est nécessaire, elle n'est pas suffisante.`),
// ---------- Maths Sup : analyse ----------
contre('ecart', 'sup', N, 'ma-07', 'Écart qui tend vers 0', T`« Si $u_{n+1} - u_n$ tend vers 0, alors la suite $(u_n)$ converge. »`, [
  [T`$u_n = \sqrt n$`, T`L'écart $\dfrac{1}{\sqrt{n+1} + \sqrt n}$ tend vers 0, et la suite tend vers $+\infty$.`, B],
  [T`$u_n = \dfrac1n$`, T`L'écart tend vers 0 et la suite converge.` + CV],
  [T`$u_n = n$`, T`L'écart vaut 1 et ne tend pas vers 0.` + HF],
  [T`$u_n = (-1)^n$`, T`L'écart vaut 2 ou $-2$ et ne tend pas vers 0.` + HF] ],
  T`La condition est nécessaire à la convergence, pas suffisante : des pas de plus en plus petits peuvent mener aussi loin que l'on veut.`),
contre('continue-bornee', 'sup', N, 'ma-08', 'Continue sur un intervalle borné', T`« Toute fonction continue sur un intervalle borné est bornée. »`, [
  [T`$x \mapsto \dfrac1x$ sur $]0, 1]$`, T`Cette fonction est continue sur un intervalle borné, et elle tend vers $+\infty$ en 0.`, B],
  [T`$x \mapsto x^2$ sur $[0, 1]$`, T`Cette fonction est continue et bornée.` + CV],
  [T`$x \mapsto \sin x$ sur $]0, 1[$`, T`Cette fonction est continue et bornée.` + CV],
  [T`$x \mapsto x$ sur $]0, 1[$`, T`Cette fonction est continue et bornée, même si elle n'atteint pas ses bornes.` + CV] ],
  T`Le théorème demande un segment, c'est-à-dire un intervalle fermé et borné.`),
contre('strictement-croissante', 'sup', N, 'ma-09', 'Strictement croissante donc dérivée strictement positive', T`« Si $f$ est dérivable et strictement croissante sur $\mathbb{R}$, alors $f'(x) > 0$ pour tout réel $x$. »`, [
  [T`$f(x) = x^3$`, T`Cette fonction est strictement croissante, et $f'(0) = 0$.`, B],
  [T`$f(x) = e^x$`, T`Cette fonction est strictement croissante et sa dérivée est strictement positive.` + CV],
  [T`$f(x) = x$`, T`Cette fonction est strictement croissante et sa dérivée vaut 1.` + CV],
  [T`$f(x) = x^2$`, T`Cette fonction n'est pas croissante sur $\mathbb{R}$.` + HF] ],
  T`$f' > 0$ entraîne la stricte croissance, pas l'inverse : la dérivée peut s'annuler en des points isolés.`),
contre('terme-general', 'sup', N, 'ma-20', 'Terme général qui tend vers 0', T`« Si $u_n$ tend vers 0, alors la série $\sum u_n$ converge. »`, [
  [T`$u_n = \dfrac1n$`, T`Le terme général tend vers 0 et la série harmonique diverge.`, B],
  [T`$u_n = \dfrac{1}{n^2}$`, T`Le terme général tend vers 0 et la série converge.` + CV],
  [T`$u_n = \dfrac{1}{2^n}$`, T`Le terme général tend vers 0 et la série converge.` + CV],
  [T`$u_n = 1$`, T`Le terme général ne tend pas vers 0.` + HF] ],
  T`C'est la réciproque qui est vraie : si la série converge, son terme général tend vers 0.`),
contre('absolue', 'sup', N, 'ma-20', 'Convergente donc absolument convergente', T`« Si la série $\sum u_n$ converge, alors la série $\sum |u_n|$ converge. »`, [
  [T`$u_n = \dfrac{(-1)^n}{n}$`, T`Cette série converge, et la série de ses valeurs absolues est la série harmonique, qui diverge.`, B],
  [T`$u_n = \dfrac{(-1)^n}{n^2}$`, T`Cette série converge, et la série des valeurs absolues aussi.` + CV],
  [T`$u_n = \dfrac{1}{n^2}$`, T`Cette série converge, et elle est égale à la série de ses valeurs absolues.` + CV],
  [T`$u_n = (-1)^n$`, T`Cette série diverge : son terme général ne tend pas vers 0.` + HF] ],
  T`La convergence absolue entraîne la convergence ; la réciproque est fausse. Une série convergente sans l'être absolument est dite semi-convergente.`),
contre('equivalents-exp', 'sup', N, 'ma-10', 'Composer un équivalent par l\'exponentielle', T`« Si $u_n \sim v_n$, alors $e^{u_n} \sim e^{v_n}$. »`, [
  [T`$u_n = n + 1$ et $v_n = n$`, T`Les suites sont équivalentes, mais $\dfrac{e^{n+1}}{e^n} = e$ ne tend pas vers 1.`, B],
  [T`$u_n = \dfrac1n$ et $v_n = \dfrac1n$`, T`Les suites sont égales, et leurs exponentielles aussi.` + CV],
  [T`$u_n = n + \dfrac1n$ et $v_n = n$`, T`Les suites sont équivalentes, et $\dfrac{e^{u_n}}{e^{v_n}} = e^{1/n}$ tend vers 1.` + CV],
  [T`$u_n = n^2$ et $v_n = n$`, T`Ces suites ne sont pas équivalentes : leur quotient tend vers $+\infty$.` + HF] ],
  T`$e^{u_n} \sim e^{v_n}$ équivaut à $u_n - v_n \to 0$, ce qui est plus fort que $u_n \sim v_n$ quand les suites tendent vers l'infini.`),
contre('derivee-nulle-constante', 'sup', N, 'ma-09', 'Dérivée nulle donc constante', T`« Une fonction dérivable dont la dérivée est nulle sur son ensemble de définition est constante. »`, [
  [T`$x \mapsto \arctan x + \arctan\dfrac1x$ sur $\mathbb{R}^*$`, T`Sa dérivée est nulle sur $\mathbb{R}^*$, mais elle vaut $\dfrac{\pi}{2}$ sur $]0, +\infty[$ et $-\dfrac{\pi}{2}$ sur $]-\infty, 0[$.`, B],
  [T`$x \mapsto 3$ sur $\mathbb{R}$`, T`Sa dérivée est nulle et elle est constante.` + CV],
  [T`$x \mapsto x$ sur $\mathbb{R}$`, T`Sa dérivée vaut 1.` + HF],
  [T`$x \mapsto \cos^2 x + \sin^2 x$ sur $\mathbb{R}$`, T`Sa dérivée est nulle et elle est constante, égale à 1.` + CV] ],
  T`Le théorème vaut sur un intervalle. Sur une réunion d'intervalles, il y a une constante par intervalle.`),
// ---------- Maths Sup : probabilités ----------
contre('deux-a-deux-independants', 'sup', Pr, 'ma-21', 'Deux à deux donc mutuellement indépendants', T`On lance des pièces équilibrées. « Trois événements deux à deux indépendants sont mutuellement indépendants. »`, [
  [T`Deux lancers ; $A$ : « pile au premier », $B$ : « pile au second », $C$ : « les deux lancers donnent le même résultat »`, T`Chaque paire est indépendante, mais $P(A \cap B \cap C) = \dfrac14$, et non $\dfrac18$.`, B],
  [T`Trois lancers ; $A$, $B$, $C$ : « pile » au premier, au deuxième, au troisième`, T`Ces événements sont deux à deux et mutuellement indépendants.` + CV],
  [T`Deux lancers ; $A$ : « pile au premier », $B$ : « pile au second », $C = A$`, T`$A$ et $C$ ne sont pas indépendants : $P(A \cap C) = \dfrac12 \neq \dfrac14$.` + HF],
  [T`Deux lancers ; $A$ : « pile au premier », $B$ : « pile au second », $C$ : l'événement impossible`, T`Toutes les formules du produit se réduisent à $0 = 0$ ou à l'indépendance de $A$ et $B$ : les événements sont mutuellement indépendants.` + CV] ],
  T`L'indépendance mutuelle de trois événements demande quatre égalités : une par paire, et une pour le triplet.`),
contre('non-correlees', 'sup', Pr, 'ma-21', 'E(XY) = E(X)E(Y) donc indépendantes', T`« Si $E(XY) = E(X)\,E(Y)$, alors $X$ et $Y$ sont indépendantes. »`, [
  [T`$X$ uniforme sur $\{-1, 0, 1\}$ et $Y = X^2$`, T`$E(XY) = E(X^3) = 0 = E(X)\,E(Y)$, alors que $Y$ est déterminée par $X$ : $P(X = 0, Y = 1) = 0$.`, B],
  [T`$X$ et $Y$ les résultats de deux dés indépendants`, T`L'égalité est vraie et les variables sont indépendantes.` + CV],
  [T`$X$ le résultat d'un dé et $Y = X$`, T`$E(X^2) = \dfrac{91}{6}$, alors que $E(X)^2 = \dfrac{49}{4}$ : l'égalité est fausse.` + HF],
  [T`$X$ constante égale à 2 et $Y$ le résultat d'un dé`, T`L'égalité est vraie, et une variable constante est indépendante de toute autre.` + CV] ],
  T`L'indépendance entraîne $E(XY) = E(X)\,E(Y)$ ; la réciproque est fausse. Des variables qui vérifient cette égalité sont dites non corrélées.`),
// ---------- Ajouts du 12 nov. au soir (inventaire des chapitres du cours, §152) ----------
contre('meme-pente', 'premiere', '', 'p-03', 'Même coefficient directeur', T`« Deux droites qui ont le même coefficient directeur sont confondues. »`, [
  [T`$y = 2x + 1$ et $y = 2x - 3$`, T`Ces droites ont le même coefficient directeur, 2, mais des ordonnées à l'origine différentes : elles sont strictement parallèles.`, B],
  [T`$y = 2x + 1$ et $y = 2x + 1$`, T`Ces deux équations décrivent la même droite.` + CV],
  [T`$y = 2x + 1$ et $y = 3x + 1$`, T`Les coefficients directeurs, 2 et 3, sont différents.` + HF],
  [T`$y = x$ et $y = -x$`, T`Les coefficients directeurs, 1 et $-1$, sont différents.` + HF] ],
  T`Même coefficient directeur signifie parallèles. Pour être confondues, deux droites doivent avoir de plus un point commun.`),
contre('exp-somme', 'premiere', '', 'p-08', 'L\'exponentielle d\'une somme', T`« Pour tous réels $a$ et $b$, $e^{a+b} = e^a + e^b$. »`, [
  [T`$a = 0$ et $b = 0$`, T`$e^{0} = 1$, alors que $e^0 + e^0 = 2$.`, B],
  [T`$a = \ln 2$ et $b = \ln 2$`, T`$e^{a+b} = 2 \times 2 = 4$ et $e^a + e^b = 2 + 2 = 4$ : l'égalité est vraie pour ces nombres.`],
  [T`$a = \ln 3$ et $b = \ln 1{,}5$`, T`$e^{a+b} = 3 \times 1{,}5 = 4{,}5$ et $e^a + e^b = 3 + 1{,}5 = 4{,}5$ : l'égalité est vraie pour ces nombres.`],
  [T`$a = \ln 4$ et $b = \ln\dfrac43$`, T`$e^{a+b} = 4 \times \dfrac43 = \dfrac{16}{3}$ et $e^a + e^b = 4 + \dfrac43 = \dfrac{16}{3}$ : l'égalité est vraie pour ces nombres.`] ],
  T`$e^{a+b} = e^a \times e^b$. L'égalité proposée n'a lieu que si les deux nombres $e^a$ et $e^b$ ont même somme et même produit.`),
contre('geometrique-croissante', 'premiere', '', 'p-02', 'Raison positive donc croissante', T`« Une suite géométrique de premier terme positif et de raison positive est croissante. »`, [
  [T`$u_0 = 1$ et $q = 2$`, T`La suite $1, 2, 4, 8, \dots$ est croissante.` + CV],
  [T`$u_0 = 1$ et $q = \dfrac12$`, T`La suite $1, \dfrac12, \dfrac14, \dots$ a un premier terme et une raison positifs, et elle est décroissante.`, B],
  [T`$u_0 = 1$ et $q = -2$`, T`La raison est négative.` + HF],
  [T`$u_0 = 3$ et $q = 1$`, T`La suite est constante, donc croissante au sens large.` + CV] ],
  T`Pour $u_0 > 0$, la suite géométrique est croissante si $q \geqslant 1$ et décroissante si $0 < q \leqslant 1$ : c'est la position de $q$ par rapport à 1 qui compte, pas son signe.`),
contre('derivee-produit', 'premiere', '', 'p-04', 'La dérivée d\'un produit', T`« Pour toutes fonctions dérivables $u$ et $v$, $(uv)' = u' \times v'$. »`, [
  [T`$u(x) = x$ et $v(x) = x$`, T`$(uv)'(x) = 2x$, alors que $u'(x)\,v'(x) = 1$.`, B],
  [T`$u(x) = 0$ et $v(x) = x^2$`, T`Les deux membres sont nuls : l'égalité est vraie pour ces fonctions.`],
  [T`$u(x) = 2$ et $v(x) = 3$`, T`Le produit est constant et les deux dérivées sont nulles : l'égalité est vraie pour ces fonctions.`],
  [T`$u(x) = e^{2x}$ et $v(x) = e^{2x}$`, T`$(uv)'(x) = 4e^{4x}$ et $u'(x)\,v'(x) = 2e^{2x} \times 2e^{2x} = 4e^{4x}$ : l'égalité est vraie pour ces fonctions.`] ],
  T`$(uv)' = u'v + uv'$. Qu'une formule fausse donne le bon résultat sur quelques exemples ne la rend pas vraie.`),
contre('conditionnelles', 'premiere', '', 'p-05', 'Inverser une probabilité conditionnelle', T`On lance un dé équilibré. « Pour tous événements $A$ et $B$ de probabilités non nulles, $P_A(B) = P_B(A)$. »`, [
  [T`$A$ : « obtenir 6 » ; $B$ : « obtenir un nombre pair »`, T`$P_A(B) = 1$, puisque 6 est pair, alors que $P_B(A) = \dfrac13$.`, B],
  [T`$A$ : « obtenir un nombre pair » ; $B$ : « obtenir un nombre impair »`, T`Les deux probabilités conditionnelles sont nulles : l'égalité est vraie ici.`],
  [T`$A$ : « obtenir 1 ou 2 » ; $B$ : « obtenir 2 ou 3 »`, T`$P_A(B) = \dfrac12$ et $P_B(A) = \dfrac12$ : l'égalité est vraie ici.`],
  [T`$A$ et $B$ : « obtenir un nombre pair »`, T`Les deux probabilités conditionnelles valent 1 : l'égalité est vraie ici.`] ],
  T`$P_A(B) = \dfrac{P(A \cap B)}{P(A)}$ et $P_B(A) = \dfrac{P(A \cap B)}{P(B)}$ : elles ne sont égales que si $P(A) = P(B)$ ou si $P(A \cap B) = 0$.`),
contre('sinus-somme', 'premiere', '', 'p-06', 'Le sinus d\'une somme', T`« Pour tous réels $a$ et $b$, $\sin(a + b) = \sin a + \sin b$. »`, [
  [T`$a = 0$ et $b = \dfrac{\pi}{2}$`, T`$\sin\dfrac{\pi}{2} = 1 = 0 + 1$ : l'égalité est vraie pour ces nombres.`],
  [T`$a = \pi$ et $b = \pi$`, T`$\sin(2\pi) = 0 = 0 + 0$ : l'égalité est vraie pour ces nombres.`],
  [T`$a = \dfrac{\pi}{2}$ et $b = \dfrac{\pi}{2}$`, T`$\sin\pi = 0$, alors que $\sin\dfrac{\pi}{2} + \sin\dfrac{\pi}{2} = 2$.`, B],
  [T`$a = 0$ et $b = 0$`, T`Les deux membres sont nuls : l'égalité est vraie pour ces nombres.`] ],
  T`Le sinus n'est pas linéaire. La formule exacte, $\sin(a + b) = \sin a\cos b + \cos a\sin b$, est établie plus tard, en Maths expertes.`),
contre('norme-somme', 'premiere', '', 'p-07', 'La norme d\'une somme', T`« Pour tous vecteurs $\vec u$ et $\vec v$, $\|\vec u + \vec v\| = \|\vec u\| + \|\vec v\|$. »`, [
  [T`$\vec u(3 ; 0)$ et $\vec v(0 ; 4)$`, T`$\|\vec u + \vec v\| = 5$, alors que $\|\vec u\| + \|\vec v\| = 7$.`, B],
  [T`$\vec u(1 ; 0)$ et $\vec v(2 ; 0)$`, T`$\|\vec u + \vec v\| = 3 = 1 + 2$ : l'égalité est vraie pour ces vecteurs, colinéaires et de même sens.`],
  [T`$\vec u(0 ; 0)$ et $\vec v(1 ; 1)$`, T`Les deux membres valent $\sqrt2$ : l'égalité est vraie pour ces vecteurs.`],
  [T`$\vec u(1 ; 1)$ et $\vec v(2 ; 2)$`, T`Les deux membres valent $3\sqrt2$ : l'égalité est vraie pour ces vecteurs, colinéaires et de même sens.`] ],
  T`$\|\vec u + \vec v\| \leqslant \|\vec u\| + \|\vec v\|$, avec égalité pour des vecteurs colinéaires et de même sens.`),
contre('factorielle-puissance', 'terminale', '', 't-07', 'Factorielle et puissance de 2', T`« Pour tout entier $n \geqslant 1$, $n! > 2^n$. »`, [
  [T`$n = 4$`, T`$4! = 24 > 16 = 2^4$ : l'énoncé est vérifié pour cet entier.`],
  [T`$n = 5$`, T`$5! = 120 > 32 = 2^5$ : l'énoncé est vérifié pour cet entier.`],
  [T`$n = 3$`, T`$3! = 6$, alors que $2^3 = 8$.`, B],
  [T`$n = 10$`, T`$10! = 3\,628\,800 > 1024 = 2^{10}$ : l'énoncé est vérifié pour cet entier.`] ],
  T`L'inégalité $n! > 2^n$ est vraie à partir de $n = 4$, et se démontre alors par récurrence. Une propriété vraie pour tous les grands entiers peut être fausse pour les premiers.`),
contre('solution-positive', 'terminale', '', 't-08', 'Solutions de y′ = y', T`« Toute solution sur $\mathbb{R}$ de l'équation $y' = y$ est strictement positive. »`, [
  [T`$y(x) = e^x$`, T`Cette fonction est solution et strictement positive.` + CV],
  [T`$y(x) = 2e^x$`, T`Cette fonction est solution et strictement positive.` + CV],
  [T`$y(x) = -e^x$`, T`Cette fonction est solution, puisque sa dérivée est $-e^x$, et elle est strictement négative.`, B],
  [T`$y(x) = e^{2x}$`, T`Sa dérivée est $2e^{2x}$ : cette fonction n'est pas solution de $y' = y$.` + HF] ],
  T`Les solutions de $y' = y$ sont les fonctions $x \mapsto Ce^x$, où $C$ est un réel quelconque, éventuellement négatif ou nul.`),
contre('cosinus-egaux', 'terminale', '', 't-09', 'Même cosinus', T`« Si $\cos x = \cos y$, alors $x = y$. »`, [
  [T`$x = 0$ et $y = 0$`, T`Les cosinus sont égaux et les nombres aussi.` + CV],
  [T`$x = \dfrac{\pi}{3}$ et $y = -\dfrac{\pi}{3}$`, T`Les deux cosinus valent $\dfrac12$, la fonction cosinus étant paire, alors que $x \neq y$.`, B],
  [T`$x = 0$ et $y = \dfrac{\pi}{2}$`, T`$\cos 0 = 1$ et $\cos\dfrac{\pi}{2} = 0$ : les cosinus sont différents.` + HF],
  [T`$x = \pi$ et $y = \pi$`, T`Les cosinus sont égaux et les nombres aussi.` + CV] ],
  T`$\cos x = \cos y$ équivaut à $x = y + 2k\pi$ ou $x = -y + 2k\pi$, avec $k$ entier.`),
contre('meme-esperance', 'terminale', '', 't-10', 'Même espérance donc même variance', T`« Deux variables aléatoires de même espérance ont la même variance. »`, [
  [T`$X$ constante égale à 0 ; $Y$ valant $-1$ ou 1 avec la probabilité $\dfrac12$`, T`Les deux espérances sont nulles, mais $V(X) = 0$ et $V(Y) = 1$.`, B],
  [T`$X$ le résultat d'un dé, et $Y = X$`, T`Même espérance et même variance.` + CV],
  [T`$X$ le résultat d'un dé, et $Y = 7 - X$`, T`$Y$ prend les mêmes valeurs que $X$ avec les mêmes probabilités : même espérance, $3{,}5$, et même variance.` + CV],
  [T`$X$ valant 0 ou 1 selon une pièce équilibrée ; $Y$ le résultat d'un dé`, T`Les espérances, $0{,}5$ et $3{,}5$, sont différentes.` + HF] ],
  T`L'espérance indique où la variable se situe en moyenne ; la variance mesure sa dispersion autour de cette moyenne. Ce sont deux informations indépendantes.`),
contre('ln-carre', 'terminale', '', 't-05', 'ln(x²) = 2 ln x', T`« Pour tout réel $x$ non nul, $\ln(x^2) = 2\ln x$. »`, [
  [T`$x = 2$`, T`$\ln 4 = 2\ln 2$ : l'égalité est vraie pour ce nombre.`],
  [T`$x = e$`, T`$\ln(e^2) = 2 = 2\ln e$ : l'égalité est vraie pour ce nombre.`],
  [T`$x = -1$`, T`$\ln\bigl((-1)^2\bigr) = \ln 1 = 0$, alors que $\ln(-1)$ n'existe pas.`, B],
  [T`$x = 1$`, T`Les deux membres sont nuls : l'égalité est vraie pour ce nombre.`] ],
  T`La formule vaut pour $x > 0$. Pour tout réel non nul, c'est $\ln(x^2) = 2\ln|x|$.`),
contre('integrale-produit', 'terminale', '', 't-06', 'L\'intégrale d\'un produit', T`Sur $[0, 1]$ : « L'intégrale d'un produit est le produit des intégrales. »`, [
  [T`$f(x) = 1$ et $g(x) = 1$`, T`Les deux membres valent 1 : l'égalité est vraie pour ces fonctions.`],
  [T`$f(x) = x$ et $g(x) = x$`, T`$\displaystyle\int_0^1 x^2\,dx = \dfrac13$, alors que $\dfrac12 \times \dfrac12 = \dfrac14$.`, B],
  [T`$f(x) = 0$ et $g(x) = x^2$`, T`Les deux membres sont nuls : l'égalité est vraie pour ces fonctions.`],
  [T`$f(x) = 1$ et $g(x) = x$`, T`Les deux membres valent $\dfrac12$ : l'égalité est vraie pour ces fonctions.`] ],
  T`L'intégrale est linéaire, pas multiplicative. Pour un produit, on pense à l'intégration par parties.`),
contre('changement-signe', 'terminale', '', 't-03', 'Changer de signe sans s\'annuler', T`« Si $f(a) \times f(b) < 0$, alors $f$ s'annule entre $a$ et $b$. »`, [
  [T`$f(x) = \dfrac1x$, $a = -1$ et $b = 1$`, T`$f(-1) \times f(1) = -1 < 0$, mais $\dfrac1x$ ne s'annule jamais : la fonction n'est pas définie en 0.`, B],
  [T`$f(x) = x$, $a = -1$ et $b = 1$`, T`Le produit est négatif et $f$ s'annule en 0.` + CV],
  [T`$f(x) = x^2$, $a = -1$ et $b = 1$`, T`$f(-1) \times f(1) = 1$ n'est pas négatif.` + HF],
  [T`$f(x) = x^3 - 1$, $a = 0$ et $b = 2$`, T`$f(0) \times f(2) = -7 < 0$ et $f$ s'annule en 1.` + CV] ],
  T`Le théorème des valeurs intermédiaires demande une fonction continue sur tout l'intervalle $[a, b]$.`),
contre('module-difference', 'expertes', '', 'me-05', 'Distance et modules', T`« Pour tous nombres complexes $z$ et $z'$, $|z - z'| = |z| - |z'|$. »`, [
  [T`$z = 3$ et $z' = 1$`, T`$|3 - 1| = 2 = 3 - 1$ : l'égalité est vraie pour ces nombres.`],
  [T`$z = 2i$ et $z' = i$`, T`$|i| = 1 = 2 - 1$ : l'égalité est vraie pour ces nombres.`],
  [T`$z = 1$ et $z' = i$`, T`$|1 - i| = \sqrt2$, alors que $|1| - |i| = 0$.`, B],
  [T`$z = 5$ et $z' = 5$`, T`Les deux membres sont nuls : l'égalité est vraie pour ces nombres.`] ],
  T`$|z - z'|$ est la distance entre les points images. On a seulement $|z - z'| \geqslant \bigl||z| - |z'|\bigr|$, avec égalité quand les points sont sur une même demi-droite issue de l'origine.`),
contre('rectangle-isocele', 'expertes', '', 'me-08', 'Imaginaire pur donc rectangle isocèle', T`Les points $A$, $B$, $C$ ont pour affixes $a$, $b$, $c$. « Si $\dfrac{c - a}{b - a}$ est imaginaire pur, alors $ABC$ est rectangle et isocèle en $A$. »`, [
  [T`$a = 0$, $b = 1$, $c = i$`, T`Le quotient vaut $i$ : le triangle est rectangle et isocèle en $A$.` + CV],
  [T`$a = 0$, $b = 1$, $c = 2i$`, T`Le quotient vaut $2i$, imaginaire pur : le triangle est rectangle en $A$, mais $AB = 1$ et $AC = 2$.`, B],
  [T`$a = 0$, $b = 1$, $c = 1 + i$`, T`Le quotient vaut $1 + i$, qui n'est pas imaginaire pur.` + HF],
  [T`$a = 0$, $b = 2$, $c = -2i$`, T`Le quotient vaut $-i$ : le triangle est rectangle et isocèle en $A$.` + CV] ],
  T`L'argument du quotient donne l'angle en $A$, son module donne le rapport $\dfrac{AC}{AB}$. Rectangle isocèle : quotient égal à $i$ ou à $-i$.`),
contre('markov-converge', 'expertes', '', 'me-09', 'Une chaîne de Markov converge toujours', T`Une chaîne de Markov à deux états part de la distribution $\begin{pmatrix} 1 & 0 \end{pmatrix}$. « La suite des distributions converge, quelle que soit la matrice de transition $P$. »`, [
  [T`$P = \begin{pmatrix} 0 & 1 \\ 1 & 0 \end{pmatrix}$`, T`Le système change d'état à chaque étape : les distributions valent alternativement $\begin{pmatrix} 1 & 0 \end{pmatrix}$ et $\begin{pmatrix} 0 & 1 \end{pmatrix}$, sans limite.`, B],
  [T`$P = \begin{pmatrix} 0{,}5 & 0{,}5 \\ 0{,}5 & 0{,}5 \end{pmatrix}$`, T`Dès la première étape, la distribution vaut $\begin{pmatrix} 0{,}5 & 0{,}5 \end{pmatrix}$ et n'en bouge plus : la suite converge.`],
  [T`$P = \begin{pmatrix} 1 & 0 \\ 0 & 1 \end{pmatrix}$`, T`Le système ne change jamais d'état : la suite des distributions est constante, donc convergente.`],
  [T`$P = \begin{pmatrix} 1 & 0 \\ 0{,}5 & 0{,}5 \end{pmatrix}$`, T`Partant du premier état, le système y reste : la suite des distributions est constante, donc convergente.`] ],
  T`La convergence demande une hypothèse sur $P$, par exemple qu'une de ses puissances n'ait aucun coefficient nul.`),
contre('non-nulle-inversible', 'expertes', '', 'me-03', 'Non nulle donc inversible', T`« Toute matrice carrée non nulle est inversible. »`, [
  [T`$\begin{pmatrix} 1 & 1 \\ 1 & 1 \end{pmatrix}$`, T`Cette matrice n'est pas nulle, mais son déterminant $1 \times 1 - 1 \times 1$ est nul : elle n'est pas inversible.`, B],
  [T`$\begin{pmatrix} 1 & 0 \\ 0 & 1 \end{pmatrix}$`, T`Cette matrice est non nulle et inversible : elle est son propre inverse.` + CV],
  [T`$\begin{pmatrix} 1 & 2 \\ 3 & 4 \end{pmatrix}$`, T`Son déterminant vaut $-2$ : elle est non nulle et inversible.` + CV],
  [T`$\begin{pmatrix} 0 & 0 \\ 0 & 0 \end{pmatrix}$`, T`Cette matrice est nulle.` + HF] ],
  T`Une matrice carrée d'ordre 2 est inversible si et seulement si son déterminant $ad - bc$ n'est pas nul.`),
contre('produit-diviseurs', 'expertes', '', 'me-07', 'Le produit de deux diviseurs', T`« Si $a$ et $b$ divisent $n$, alors $ab$ divise $n$. »`, [
  [T`$a = 4$, $b = 6$, $n = 12$`, T`4 et 6 divisent 12, mais leur produit 24 ne le divise pas.`, B],
  [T`$a = 2$, $b = 3$, $n = 12$`, T`2 et 3 divisent 12, et 6 aussi.` + CV],
  [T`$a = 3$, $b = 4$, $n = 12$`, T`3 et 4 divisent 12, et leur produit 12 aussi.` + CV],
  [T`$a = 5$, $b = 2$, $n = 12$`, T`5 ne divise pas 12.` + HF] ],
  T`L'énoncé est vrai quand $a$ et $b$ sont premiers entre eux. En général, c'est leur PPCM qui divise $n$.`),
contre('impair-premier', 'expertes', '', 'me-01', 'Impair donc premier', T`« Tout entier impair supérieur ou égal à 3 est premier. »`, [
  [T`$3$`, T`3 est impair et premier : l'énoncé est vérifié pour cet entier.`],
  [T`$7$`, T`7 est impair et premier : l'énoncé est vérifié pour cet entier.`],
  [T`$9$`, T`9 est impair, et $9 = 3 \times 3$ n'est pas premier.`, B],
  [T`$13$`, T`13 est impair et premier : l'énoncé est vérifié pour cet entier.`] ],
  T`Tout nombre premier autre que 2 est impair ; la réciproque est fausse.`),
contre('quantificateurs', 'sup', F, 'ma-01', 'Échanger deux quantificateurs', T`Sur $\mathbb{N}$ : « Si $\forall x,\ \exists y,\ R(x, y)$, alors $\exists y,\ \forall x,\ R(x, y)$. »`, [
  [T`$R(x, y)$ : « $y > x$ »`, T`Tout entier a un entier plus grand, mais aucun entier n'est plus grand que tous les autres.`, B],
  [T`$R(x, y)$ : « $y \leqslant x$ »`, T`Les deux assertions sont vraies : $y = 0$ convient à tous les $x$.` + CV],
  [T`$R(x, y)$ : « $y < x$ »`, T`Pour $x = 0$, aucun entier naturel $y$ ne convient : la première assertion est fausse.` + HF],
  [T`$R(x, y)$ : « $xy = 0$ »`, T`Les deux assertions sont vraies : $y = 0$ convient à tous les $x$.` + CV] ],
  T`Dans $\forall x\,\exists y$, le $y$ dépend de $x$. Dans $\exists y\,\forall x$, un même $y$ convient à tous.`),
contre('somme-produits', 'sup', F, 'ma-03', 'Somme de produits', T`Pour des réels $a_1, a_2, b_1, b_2$ : « $a_1 b_1 + a_2 b_2 = (a_1 + a_2)(b_1 + b_2)$. »`, [
  [T`$(a_1, a_2) = (1, 1)$ et $(b_1, b_2) = (1, 1)$`, T`Le premier membre vaut 2, le second 4.`, B],
  [T`$(a_1, a_2) = (1, 0)$ et $(b_1, b_2) = (1, 0)$`, T`Les deux membres valent 1 : l'égalité est vraie ici.`],
  [T`$(a_1, a_2) = (0, 0)$ et $(b_1, b_2) = (3, 5)$`, T`Les deux membres sont nuls : l'égalité est vraie ici.`],
  [T`$(a_1, a_2) = (2, 0)$ et $(b_1, b_2) = (3, 0)$`, T`Les deux membres valent 6 : l'égalité est vraie ici.`] ],
  T`Le produit de deux sommes contient les termes croisés $a_1 b_2$ et $a_2 b_1$ : $\displaystyle\sum a_k b_k \neq \left(\sum a_k\right)\left(\sum b_k\right)$ en général.`),
contre('pythagore-complexe', 'sup', A, 'ma-04', 'Module d\'une somme, au carré', T`« Pour tous nombres complexes $z$ et $z'$, $|z + z'|^2 = |z|^2 + |z'|^2$. »`, [
  [T`$z = 1$ et $z' = i$`, T`$|1 + i|^2 = 2 = 1 + 1$ : l'égalité est vraie pour ces nombres.`],
  [T`$z = 1$ et $z' = 1$`, T`$|2|^2 = 4$, alors que $1 + 1 = 2$.`, B],
  [T`$z = 2$ et $z' = 3i$`, T`$|2 + 3i|^2 = 13 = 4 + 9$ : l'égalité est vraie pour ces nombres.`],
  [T`$z = 0$ et $z' = 5$`, T`Les deux membres valent 25 : l'égalité est vraie pour ces nombres.`] ],
  T`$|z + z'|^2 = |z|^2 + 2\,\mathrm{Re}(z\overline{z'}) + |z'|^2$ : l'égalité proposée est le théorème de Pythagore, vrai quand les vecteurs images sont orthogonaux.`),
contre('arctan-tan', 'sup', N, 'ma-05', 'arctan(tan x) = x', T`« Pour tout réel $x$ où la tangente est définie, $\arctan(\tan x) = x$. »`, [
  [T`$x = 0$`, T`$\arctan(\tan 0) = \arctan 0 = 0$ : l'égalité est vraie pour ce nombre.`],
  [T`$x = \dfrac{\pi}{4}$`, T`$\arctan 1 = \dfrac{\pi}{4}$ : l'égalité est vraie pour ce nombre.`],
  [T`$x = \pi$`, T`$\tan\pi = 0$, donc $\arctan(\tan\pi) = 0$, et non $\pi$.`, B],
  [T`$x = -\dfrac{\pi}{3}$`, T`$\arctan\bigl(-\sqrt3\bigr) = -\dfrac{\pi}{3}$ : l'égalité est vraie pour ce nombre.`] ],
  T`L'arctangente prend ses valeurs dans $\left]-\dfrac{\pi}{2}, \dfrac{\pi}{2}\right[$ : l'égalité $\arctan(\tan x) = x$ n'a lieu que sur cet intervalle. En revanche $\tan(\arctan y) = y$ pour tout réel $y$.`),
contre('primitive-carre', 'sup', N, 'ma-06', 'Primitive d\'un carré', T`« Si $F$ est une primitive de $f$ sur $\mathbb{R}$, alors $F^2$ est une primitive de $f^2$. »`, [
  [T`$f(x) = 1$ et $F(x) = x$`, T`$F^2(x) = x^2$ a pour dérivée $2x$, alors que $f^2(x) = 1$.`, B],
  [T`$f(x) = 0$ et $F(x) = 0$`, T`$F^2$ et $f^2$ sont nulles : l'énoncé est vérifié ici.`],
  [T`$f(x) = 2e^{2x}$ et $F(x) = e^{2x}$`, T`$F^2(x) = e^{4x}$ a pour dérivée $4e^{4x}$, qui est bien $f^2(x)$ : l'énoncé est vérifié ici.`],
  [T`$f(x) = 0$ et $F(x) = -2$`, T`$F^2$ est constante, de dérivée nulle, et $f^2$ est nulle : l'énoncé est vérifié ici.`] ],
  T`$(F^2)' = 2FF' = 2Ff$, qui n'est pas $f^2$. La primitivation est linéaire ; elle ne respecte ni les produits ni les carrés.`),
contre('gauss-sans-hypothese', 'sup', A, 'ma-12', 'Gauss sans « premiers entre eux »', T`« Si $a$ divise $bc$ et ne divise pas $b$, alors $a$ divise $c$. »`, [
  [T`$a = 6$, $b = 4$, $c = 9$`, T`6 divise 36 et ne divise pas 4 ; pourtant il ne divise pas 9.`, B],
  [T`$a = 3$, $b = 4$, $c = 9$`, T`3 divise 36, ne divise pas 4, et divise 9.` + CV],
  [T`$a = 5$, $b = 2$, $c = 10$`, T`5 divise 20, ne divise pas 2, et divise 10.` + CV],
  [T`$a = 4$, $b = 4$, $c = 3$`, T`4 divise $b = 4$.` + HF] ],
  T`Le théorème de Gauss demande que $a$ soit premier avec $b$, ce qui est plus fort que « $a$ ne divise pas $b$ ».`),
contre('identite-remarquable', 'sup', L, 'ma-16', 'Identité remarquable pour des matrices', T`« Pour toutes matrices $A$ et $B$ de $\mathcal{M}_2(\mathbb{R})$, $(A + B)^2 = A^2 + 2AB + B^2$. »`, [
  [T`$A = \begin{pmatrix} 0 & 1 \\ 0 & 0 \end{pmatrix}$ et $B = \begin{pmatrix} 0 & 0 \\ 1 & 0 \end{pmatrix}$`, T`$(A + B)^2 = I_2$, alors que $A^2 + 2AB + B^2 = \begin{pmatrix} 2 & 0 \\ 0 & 0 \end{pmatrix}$.`, B],
  [T`$A = I_2$ et $B = \begin{pmatrix} 1 & 2 \\ 3 & 4 \end{pmatrix}$`, T`$I_2$ commute avec toute matrice : l'égalité est vraie ici.`],
  [T`$A = B = \begin{pmatrix} 1 & 2 \\ 3 & 4 \end{pmatrix}$`, T`Les deux membres valent $4A^2$ : l'égalité est vraie ici.`],
  [T`$A = 2I_2$ et $B = \begin{pmatrix} 1 & 2 \\ 3 & 4 \end{pmatrix}$`, T`$2I_2$ commute avec toute matrice : l'égalité est vraie ici.`] ],
  T`$(A + B)^2 = A^2 + AB + BA + B^2$ : l'identité remarquable vaut si et seulement si $AB = BA$.`),
contre('valeur-absolue-integrale', 'sup', N, 'ma-18', 'Valeur absolue et intégrale', T`« Pour toute fonction $f$ continue sur $[a, b]$, $\left|\displaystyle\int_a^b f\right| = \displaystyle\int_a^b |f|$. »`, [
  [T`$f(x) = x$ sur $[-1, 1]$`, T`L'intégrale de $f$ est nulle, alors que celle de $|f|$ vaut 1.`, B],
  [T`$f(x) = x$ sur $[0, 1]$`, T`Les deux membres valent $\dfrac12$ : l'égalité est vraie ici.`],
  [T`$f(x) = -1$ sur $[0, 1]$`, T`Les deux membres valent 1 : l'égalité est vraie ici.`],
  [T`$f(x) = x^2$ sur $[-1, 1]$`, T`Les deux membres valent $\dfrac23$ : l'égalité est vraie ici.`] ],
  T`$\left|\displaystyle\int_a^b f\right| \leqslant \displaystyle\int_a^b |f|$, avec égalité quand $f$ garde un signe constant.`),
contre('pythagore-toujours', 'sup', L, 'ma-19', 'Pythagore sans orthogonalité', T`Dans $\mathbb{R}^2$ muni du produit scalaire usuel : « Pour tous vecteurs $x$ et $y$, $\|x + y\|^2 = \|x\|^2 + \|y\|^2$. »`, [
  [T`$x = (1, 0)$ et $y = (0, 1)$`, T`Les deux membres valent 2 : l'égalité est vraie pour ces vecteurs, qui sont orthogonaux.`],
  [T`$x = (1, 0)$ et $y = (1, 0)$`, T`$\|x + y\|^2 = 4$, alors que $\|x\|^2 + \|y\|^2 = 2$.`, B],
  [T`$x = (0, 0)$ et $y = (2, 3)$`, T`Les deux membres valent 13 : l'égalité est vraie pour ces vecteurs.`],
  [T`$x = (1, 1)$ et $y = (1, -1)$`, T`Les deux membres valent 4 : l'égalité est vraie pour ces vecteurs, qui sont orthogonaux.`] ],
  T`$\|x + y\|^2 = \|x\|^2 + 2\langle x, y \rangle + \|y\|^2$ : l'égalité de Pythagore équivaut à l'orthogonalité.`),
contre('partielles-continue', 'sup', N, 'ma-22', 'Dérivées partielles donc continue', T`« Une fonction de $\mathbb{R}^2$ dans $\mathbb{R}$ qui admet des dérivées partielles en $(0, 0)$ est continue en $(0, 0)$. »`, [
  [T`$f(x, y) = \dfrac{xy}{x^2 + y^2}$ si $(x, y) \neq (0, 0)$, et $f(0, 0) = 0$`, T`$f$ est nulle sur les deux axes, donc ses dérivées partielles en $(0, 0)$ existent ; mais $f(t, t) = \dfrac12$ ne tend pas vers 0.`, B],
  [T`$f(x, y) = x + y$`, T`Cette fonction a des dérivées partielles et elle est continue.` + CV],
  [T`$f(x, y) = |x| + |y|$`, T`$x \mapsto |x|$ n'est pas dérivable en 0 : les dérivées partielles en $(0, 0)$ n'existent pas.` + HF],
  [T`$f(x, y) = x^2 + y^2$`, T`Cette fonction a des dérivées partielles et elle est continue.` + CV] ],
  T`Les dérivées partielles ne renseignent que sur les deux axes. C'est la classe $\mathcal{C}^1$ qui entraîne la continuité.`),
contre('reunion-sous-espaces', 'sup', L, 'ma-14', 'Réunion de sous-espaces', T`Dans $\mathbb{R}^2$ : « La réunion de deux sous-espaces vectoriels est un sous-espace vectoriel. »`, [
  [T`L'axe des abscisses et l'axe des ordonnées`, T`La réunion contient $(1, 0)$ et $(0, 1)$, mais pas leur somme $(1, 1)$.`, B],
  [T`L'axe des abscisses et $\{(0, 0)\}$`, T`La réunion est l'axe des abscisses : c'est un sous-espace.`],
  [T`L'axe des abscisses et $\mathbb{R}^2$`, T`La réunion est $\mathbb{R}^2$ : c'est un sous-espace.`],
  [T`L'axe des abscisses et lui-même`, T`La réunion est l'axe des abscisses : c'est un sous-espace.`] ],
  T`La réunion de deux sous-espaces est un sous-espace si et seulement si l'un contient l'autre. Le plus petit sous-espace qui les contient tous deux est leur somme.`),
contre('det-homogene', 'sup', L, 'ma-17', 'Déterminant d\'un multiple', T`« Pour tout réel $\lambda$ et toute matrice $A$ de $\mathcal{M}_2(\mathbb{R})$, $\det(\lambda A) = \lambda \det A$. »`, [
  [T`$\lambda = 2$ et $A = I_2$`, T`$\det(2I_2) = 4$, alors que $2\det I_2 = 2$.`, B],
  [T`$\lambda = 1$ et $A = \begin{pmatrix} 1 & 2 \\ 3 & 4 \end{pmatrix}$`, T`Les deux membres valent $\det A$ : l'égalité est vraie ici.`],
  [T`$\lambda = 3$ et $A = \begin{pmatrix} 1 & 1 \\ 1 & 1 \end{pmatrix}$`, T`Les deux déterminants sont nuls : l'égalité est vraie ici.`],
  [T`$\lambda = 0$ et $A = I_2$`, T`Les deux membres sont nuls : l'égalité est vraie ici.`] ],
  T`$\det(\lambda A) = \lambda^n \det A$ pour une matrice de taille $n$ : chaque colonne est multipliée par $\lambda$.`),
contre('union-additive', 'sup', Pr, 'ma-21', 'Probabilité d\'une réunion', T`On lance un dé équilibré. « Pour tous événements $A$ et $B$, $P(A \cup B) = P(A) + P(B)$. »`, [
  [T`$A$ : « obtenir un nombre pair » ; $B$ : « obtenir 6 »`, T`$A \cup B = A$, de probabilité $\dfrac12$, alors que $P(A) + P(B) = \dfrac12 + \dfrac16$.`, B],
  [T`$A$ : « obtenir un nombre pair » ; $B$ : « obtenir un nombre impair »`, T`Les événements sont incompatibles : les deux membres valent 1.`],
  [T`$A$ : « obtenir 1 » ; $B$ : « obtenir 2 »`, T`Les événements sont incompatibles : les deux membres valent $\dfrac13$.`],
  [T`$A$ : l'événement impossible ; $B$ : « obtenir un nombre pair »`, T`Les deux membres valent $\dfrac12$ : l'égalité est vraie ici.`] ],
  T`$P(A \cup B) = P(A) + P(B) - P(A \cap B)$ : l'additivité simple vaut pour des événements incompatibles.`),
contre('somme-divergentes', 'sup', N, 'ma-07', 'Somme de deux suites divergentes', T`« La somme de deux suites divergentes est divergente. »`, [
  [T`$u_n = n$ et $v_n = -n$`, T`Les deux suites divergent, et leur somme est la suite nulle, qui converge.`, B],
  [T`$u_n = n$ et $v_n = n$`, T`Les deux suites divergent, et leur somme $2n$ aussi.` + CV],
  [T`$u_n = (-1)^n$ et $v_n = \dfrac1n$`, T`La suite $(v_n)$ converge vers 0.` + HF],
  [T`$u_n = n$ et $v_n = (-1)^n$`, T`Les deux suites divergent, et leur somme tend vers $+\infty$, donc diverge.` + CV] ],
  T`Ce qui est vrai : la somme d'une suite convergente et d'une suite divergente est divergente.`),
contre('equivalent-difference', 'sup', N, 'ma-10', 'Équivalentes donc de différence nulle', T`« Si $u_n \sim v_n$, alors $u_n - v_n$ tend vers 0. »`, [
  [T`$u_n = n + 1$ et $v_n = n$`, T`Le quotient tend vers 1, donc les suites sont équivalentes ; mais leur différence vaut 1.`, B],
  [T`$u_n = \dfrac1n + \dfrac{1}{n^2}$ et $v_n = \dfrac1n$`, T`Les suites sont équivalentes et leur différence $\dfrac{1}{n^2}$ tend vers 0.` + CV],
  [T`$u_n = n^2$ et $v_n = n$`, T`Le quotient tend vers $+\infty$ : les suites ne sont pas équivalentes.` + HF],
  [T`$u_n = 1 + \dfrac1n$ et $v_n = 1$`, T`Les suites sont équivalentes et leur différence $\dfrac1n$ tend vers 0.` + CV] ],
  T`$u_n \sim v_n$ signifie $u_n - v_n = o(v_n)$ : la différence est négligeable devant $v_n$, pas devant 1.`),
];
